    <tr>\\n      <th>Spell<\\/th>\\n      <th>School<\\/th>\\n      <th>Special<\\/th>\\n    <\\/tr>\\n  <\\/thead>\\n  <tbody>\\n    <tr>\\n      <td>Astral Projection<\\/td>\\n      <td>Necromancy<\\/td>\\n      <td>M<\\/td>\\n    <\\/tr>\\n    <tr>\\n      <td>Gate<\\/td>\\n      <td>Conjuration<\\/td>\\n      <td>C, M<\\/td>\\n    <\\/tr>\\n    <tr>\\n      <td>Mass Heal<\\/td>\\n      <td>Abjuration<\\/td>\\n      <td>—<\\/td>\\n    <\\/tr>\\n    <tr>\\n      <td>Power Word Heal<\\/td>\\n      <td>Enchantment<\\/td>\\n      <td>—<\\/td>\\n    <\\/tr>\\n    <tr>\\n      <td>True Resurrection<\\/td>\\n      <td>Necromancy<\\/td>\\n      <td>M<\\/td>\\n    <\\/tr>\\n  <\\/tbody>\\n<\\/table>\"}]', '[{\"level\":1,\"prof_bonus\":2,\"class_specific\":{\"channel_divinity\":\"—\",\"cantrips\":3,\"prepared_spells\":4,\"spell_slots_1\":2,\"spell_slots_2\":\"-\",\"spell_slots_3\":\"-\",\"spell_slots_4\":\"-\",\"spell_slots_5\":\"-\",\"spell_slots_6\":\"-\",\"spell_slots_7\":\"-\",\"spell_slots_8\":\"-\",\"spell_slots_9\":\"-\"}},{\"level\":2,\"prof_bonus\":2,\"class_specific\":{\"channel_divinity\":\"2\",\"cantrips\":3,\"prepared_spells\":5,\"spell_slots_1\":3,\"spell_slots_2\":\"-\",\"spell_slots_3\":\"-\",\"spell_slots_4\":\"-\",\"spell_slots_5\":\"-\",\"spell_slots_6\":\"-\",\"spell_slots_7\":\"-\",\"spell_slots_8\":\"-\",\"spell_slots_9\":\"-\"}},{\"level\":3,\"prof_bonus\":2,\"class_specific\":{\"channel_divinity\":\"2\",\"cantrips\":3,\"prepared_spells\":6,\"spell_slots_1\":4,\"spell_slots_2\":2,\"spell_slots_3\":\"-\",\"spell_slots_4\":\"-\",\"spell_slots_5\":\"-\",\"spell_slots_6\":\"-\",\"spell_slots_7\":\"-\",\"spell_slots_8\":\"-\",\"spell_slots_9\":\"-\"}},{\"level\":4,\"prof_bonus\":2,\"class_specific\":{\"channel_divinity\":\"2\",\"cantrips\":4,\"prepared_spells\":7,\"spell_slots_1\":4,\"spell_slots_2\":3,\"spell_slots_3\":\"-\",\"spell_slots_4\":\"-\",\"spell_slots_5\":\"-\",\"spell_slots_6\":\"-\",\"spell_slots_7\":\"-\",\"spell_slots_8\":\"-\",\"spell_slo