warm<\\/td>\\n      <td>Evocation<\\/td>\\n      <td>—<\\/td>\\n    <\\/tr>\\n    <tr>\\n      <td>Power Word Kill<\\/td>\\n      <td>Enchantment<\\/td>\\n      <td>—<\\/td>\\n    <\\/tr>\\n    <tr>\\n      <td>Time Stop<\\/td>\\n      <td>Transmutation<\\/td>\\n      <td>—<\\/td>\\n    <\\/tr>\\n    <tr>\\n      <td>Wish<\\/td>\\n      <td>Conjuration<\\/td>\\n      <td>—<\\/td>\\n    <\\/tr>\\n  <\\/tbody>\\n<\\/table>\"}]', '[{\"level\":1,\"prof_bonus\":2,\"class_specific\":{\"sorcery_points\":\"-\",\"cantrips\":\"4\",\"prepared_spells\":\"2\"},\"spell_slots\":[\"2\",\"-\",\"-\",\"-\",\"-\",\"-\",\"-\",\"-\",\"-\"]},{\"level\":2,\"prof_bonus\":2,\"class_specific\":{\"sorcery_points\":\"2\",\"cantrips\":\"4\",\"prepared_spells\":\"4\"},\"spell_slots\":[\"3\",\"-\",\"-\",\"-\",\"-\",\"-\",\"-\",\"-\",\"-\"]},{\"level\":3,\"prof_bonus\":2,\"class_specific\":{\"sorcery_points\":\"3\",\"cantrips\":\"4\",\"prepared_spells\":\"6\"},\"spell_slots\":[\"4\",\"2\",\"-\",\"-\",\"-\",\"-\",\"-\",\"-\",\"-\"]},{\"level\":4,\"prof_bonus\":2,\"class_specific\":{\"sorcery_points\":\"4\",\"cantrips\":\"5\",\"prepared_spells\":\"7\"},\"spell_slots\":[\"4\",\"3\",\"-\",\"-\",\"-\",\"-\",\"-\",\"-\",\"-\"]},{\"level\":5,\"prof_bonus\":3,\"class_specific\":{\"sorcery_points\":\"5\",\"cantrips\":\"5\",\"prepared_spells\":\"9\"},\"spell_slots\":[\"4\",\"3\",\"2\",\"-\",\"-\",\"-\",\"-\",\"-\",\"-\"]},{\"level\":6,\"prof_bonus\":3,\"class_specific\":{\"sorcery_points\":\"6\",\"cantrips\":\"5\",\"prepared_spells\":\"10\"},\"spell_slots\":[\"4\",\"3\",\"3\",\"-\",\"-\",\"-\",\"-\",\"-\",\"-\"]},{\"level\":7,\"prof_bonus\":3,\"class_specific\":{\"sorcery_points\":\"7\",\"cantrips\":\"5\",\"prepared_spells\":\"11\"},\"spell_slots\":[\"4\",\"3\",\"3\",\"1\",\"-\",\"-\",\"-\",\"-\",\"-\"]},{\"level\":8,\"prof_bonus\":3,\"class_specific\":{\"sorcery_points\":\"8\",\"cantrips\":\"5\",\"prepared_spells\":\"12\"},\"spell_slots\":[\"4\",\"3\",\"3\",\"2\",\"-\",\"-\",\"-\",\"-\",\"-\"]},{\"level\":9,\"prof_bonus\":4,\"class_specific\":{\"sorcery_points\":\"9\",\"cantrips\":\"5\",\"prepared_spells\":\"14\"},\"spell_slots\":[\"4\",\"3\",\"3\",\"3\",\"1\",\"-\",\"-\",\"-\",\"-\"]},{\"level\":10,\"prof_bonus\":4,\"class_specific\":{\"sorcery_points\":\"10\",\"cantrips\":\"6\",\"prepared_spells\":\"15\"},\"spell_slots\":[\"4\",\"3\",\"3\",\"3\",\"2\",\"-\",\"-\",\"-\",\"-\"]},{\"level\":11,\"prof_bonus\":4,\"class_specific\":{\"sorcery_points\":\"11\",\"cantrips\":\"6\",\"prepared_spells\":\"16\"},\"spell_slots\":[\"4\",\"3\",\"3\",\"3\",\"2\",\"1\",\"-\",\"-\",\"-\"]},{\"level\":12,\"prof_bonus\":4,\"class_specific\":{\"sorcery_points\":\"12\",\"cantrips\":\"6\",\"prepared_spells\":\"16\"},\"spell_slots\":[\"4\",\"3\",\"3\",\"3\",\"2\",\"1\",\"-\",\"-\",\"-\"]},{\"level\":13,\"prof_bonus\":5,\"class_specific\":{\"sorcery_points\":\"13\",\"cantrips\":\"6\",\"prepared_spells\":\"17\"},\"spell_slots\":[\"4\",\"3\",\"3\",\"3\",\"2\",\"1\",\"1\",\"-\",\"-\"]},{\"level\":14,\"prof_bonus\":5,\"class_specific\":{\"sorcery_points\":\"14\",\"cantrips\":\"6\",\"prepared_spells\":\"17\"},\"spell_slots\":[\"4\",\"3\",\"3\",\"3\",\"2\",\"1\",\"1\",\"-\",\"-\"]},{\"level\":15,\"prof_bonus\":5,\"class_specific\":{\"sorcery_points\":\"15\",\"cantrips\":\"6\",\"prepared_spells\":\"18\"},\"spell_slots\":[\"4\",\"3\",\"3\",\"3\",\"2\",\"1\",\"1\",\"1\",\"-\"]},{\"level\":16,\"prof_bonus\":5,\"class_specific\":{\"sorcery_points\":\"16\",\"cantrips\":\"6\",\"prepared_spells\":\"18\"},\"spell_slots\":[\"4\",\"3\",\"3\",\"3\",\"2\",\"1\",\"1\",\"1\",\"-\"]},{\"level\":17,\"prof_bonus\":6,\"class_specific\":{\"sorcery_points\":\"17\",\"cantrips\":\"6\",\"prepared_spells\":\"19\"},\"spell_slots\":[\"4\",\"3\",\"3\",\"3\",\"2\",\"1\",\"1\",\"1\",\"1\"]},{\"level\":18,\"prof_bonus\":6,\"class_specific\":{\"sorcery_points\":\"18\",\"cantrips\":\"6\",\"prepared_spells\":\"20\"},\"spell_slots\":[\"4\",\"3\",\"3\",\"3\",\"3\",\"1\",\"1\",\"1\",\"1\"]},{\"level\":19,\"prof_bonus\":6,\"class_specific\":{\"sorcery_points\":\"19\",\"cantrips\":\"6\",\"prepared_spells\":\"21\"},\"spell_slots\":[\"4\",\"3\",\"3\",\"3\",\"3\",\"2\",\"1\",\"1\",\"1\"]},{\"level\":20,\"prof_bonus\":6,\"class_specific\":{\"sorcery_points\":\"20\",\"cantrips\":\"6\",\"prepared_spells\":\"22\"},\"spell_slots\":[\"4\",\"3\",\"3\",\"3\",\"3\",\"2\",\"2\",\"1\",\"1\"]}]', '{\"primary_ability\":\"Charisma\",\"hit_point_die\":\"D6 per Sorcerer level\",\"saving_throws\":[\"Constitution\",\"Charisma\"],\"skills\":{\"choose\":2,\"options\":[\"Arcana\",\"Deception\",\"Insight\",\"Intimidation\",\"Persuasion\",\"Religion\"]},\"weapon_proficiencies\":[\"Simple weapons\"],\"armor_training\":[\"None\"],\"starting_equipment\":\"Choose A or B: (A) Spear, 2 Daggers, Arcane Focus (crystal), Dungeoneer\'s Pack, and 28 GP; or (B) 50 GP\"}', '[\"absorb-elements\",\"acid-splash\",\"animate-objects\",\"arcane-gate\",\"banishment\",\"blade-ward\",\"blight\",\"blindness-deafness\",\"blur\",\"burning-hands\",\"chain-lightning\",\"charm-person\",\"chill-touch\",\"chromatic-orb\",\"circle-of-death\",\"clairvoyance\",\"cloudkill\",\"color-spray\",\"cone-of-cold\",\"confusion\",\"counterspell\",\"creation\",\"dancing-lights\",\"darkness\",\"darkvision\",\"delayed-blast-fireball\",\"detect-magic\",\"detect-thoughts\",\"dimension-door\",\"disintegrate\",\"dispel-magic\",\"dominate-beast\",\"dominate-monster\",\"dominate-person\",\"dragons-breath\",\"earthquake\",\"elementalism\",\"enhance-ability\",\"enlarge-reduce\",\"etherealness\",\"expeditious-retreat\",\"eyebite\",\"fear\",\"feather-fall\",\"finger-of-death\",\"fire-bolt\",\"fire-shield\",\"fire-storm\",\"fireball\",\"flaming-sphere\",\"fly\",\"fog-cloud\",\"freezing-sphere\",\"gaseous-form\",\"gate\",\"globe-of-invulnerability\",\"haste\",\"hold-monster\",\"hold-person\",\"hypnotic-pattern\",\"ice-storm\",\"incendiary-cloud\",\"insect-plague\",\"invisibility\",\"jump\",\"knock\",\"levitate\",\"light\",\"lightning-bolt\",\"mage-armor\",\"mage-hand\",\"magic-missile\",\"major-image\",\"mass-suggestion\",\"mending\",\"message\",\"meteor-swarm\",\"minor-illusion\",\"mirror-image\",\"misty-step\",\"move-earth\",\"plane-shift\",\"poison-spray\",\"polymorph\",\"power-word-kill\",\"power-word-stun\",\"prismatic-spray\",\"protection-from-energy\",\"ray-of-frost\",\"ray-of-sickness\",\"reverse-gravity\",\"scorching-ray\",\"see-invisibility\",\"seeming\",\"shatter\",\"shield\",\"shocking-grasp\",\"silent-image\",\"sleep\",\"sleet-storm\",\"slow\",\"sorcerous-burst\",\"spider-climb\",\"stinking-cloud\",\"stoneskin\",\"suggestion\",\"sunbeam\",\"sunburst\",\"telekinesis\",\"telepathy\",\"teleport\",\"teleportation-circle\",\"thunderwave\",\"time-stop\",\"tongues\",\"true-seeing\",\"true-strike\",\"vitriolic-sphere\",\"wall-of-fire\",\"wall-of-stone\",\"water-breathing\",\"web\",\"wish\"]', 0, NULL, NULL);
INSERT INTO `classes` (`class_id`, `class_name`, `hit_die`, `primary_ability`, `class_desc`, `hit_points`, `proficiencies`, `equipment`, `becoming`, `multiclassing`, `srd_source`, `features`, `level_progression`, `core_traits`, `spell_list`, `is_homebrew`, `author_id`, `deleted_at`) VALUES
('warlock', 'Warlock', 8, 'Charisma', 'A wielder of magic that is derived from a bargain with an extraplanar entity. Warlocks are seekers of the knowledge that lies hidden in the fabric of the multiverse.', '{\r\n    \"logic\": {\"die_sides\": 8, \"base\": 8, \"average\": 5, \"stat_modifier\": \"Constitution\"},\r\n    \"display\": {\r\n      \"hit_dice\": \"1d8 per Warlock level\",\r\n      \"hp_at_level_1\": \"8 + your Constitution modifier\",\r\n      \"hp_higher_levels\": \"1d8 (or 5) + your Constitution modifier per Warlock level after 1st\"\r\n    }\r\n  }', '{\r\n    \"granted\": {\r\n      \"armor\": [\"Light armor\"],\r\n      \"weapons\": [\"Simple weapons\"],\r\n      \"tools\": [],\r\n      \"saving_throws\": [\"Wisdom\", \"Charisma\"]\r\n    },\r\n    \"choices\": [\r\n      {\"type\": \"skills\", \"choose\": 2, \"options\": [\"Arcana\", \"Deception\", \"History\", \"Intimidation\", \"Investigation\", \"Nature\", \"Religion\"]}\r\n    ],\r\n    \"display\": {\"skills\": \"Choose two from Arcana, Deception, History, Intimidation, Investigation, Nature, and Religion\"}\r\n  }', '[\"Leather Armor\", \"Light Crossbow\", \"20 Bolts\", \"2 Daggers\", \"Arcane Focus\", \"Scholar\'s Pack\", \"15 GP\"]', NULL, '{\"requirements\": \"Charisma 13+\", \"proficiencies_gained\": {\"armor\": [\"Light armor\"], \"weapons\": [\"Simple weapons\"]}}', 'SRD 5.2.1, Page 85', '[{\"level\":1,\"name\":\"Eldritch Invocations\",\"description\":\"<p style=\'margin-bottom: 15px; line-height: 1.6;\'>You have unearthed Eldritch Invocations, pieces of forbidden knowledge that imbue you with an abiding magical ability or other lessons. You gain one invocation of your choice, such as Pact of the Tome. Invocations are described in the \\\"Eldritch Invocation Options\\\" section later in this class\'s description.<\\/p><p style=\'margin-bottom: 15px; line-height: 1.6;\'><em>Prerequisites.<\\/em> If an invocation has a prerequisite, you must meet it to learn that invocation. For example, if an invocation requires you to be a level 5+ Warlock, you can select the invocation once you reach Warlock level 5.<\\/p><p style=\'margin-bottom: 15px; line-height: 1.6;\'><em>Replacing and Gaining Invocations.<\\/em> Whenever you gain a Warlock level, you can replace one of your invocations with another one for which you qualify. You can\'t replace an invocation if it\'s a prerequisite for another invocation that you have.<\\/p><p style=\'margin-bottom: 15px; line-height: 1.6;\'>When you gain certain Warlock levels, you gain more invocations of your choice, as shown in the Invocations column of the Warlock Features table.<\\/p><p style=\'margin-bottom: 15px; line-height: 1.6;\'>You can\'t pick the same invocation more than once unless its description says otherwise.<\\/p>\",\"modifiers\":[],\"desc\":\"<p style=\'margin-bottom: 15px; line-height: 1.6;\'>You have unearthed Eldritch Invocations, pieces of forbidden knowledge that imbue you with an abiding magical ability or other lessons. You gain one invocation of your choice, such as Pact of the Tome. Invocations are described in the \\\"Eldritch Invocation Options\\\" section later in this class\'s description.<\\/p><p style=\'margin-bottom: 15px; line-height: 1.6;\'><em>Prerequisites.<\\/em> If an invocation has a prerequisite, you must meet it to learn that invocation. For example, if an invocation requires you to be a level 5+ Warlock, you can select the invocation once you reach Warlock level 5.<\\/p><p style=\'margin-bottom: 15px; line-height: 1.6;\'><em>Replacing and Gaining Invocations.<\\/em> Whenever you gain a Warlock level, you can replace one of your invocations with another one for which you qualify. You can\'t replace an invocation if it\'s a prerequisite for another invocation that you have.<\\/p><p style=\'margin-bottom: 15px; line-height: 1.6;\'>When you gain certain Warlock levels, you gain more invocations of your choice, as shown in the Invocations column of the Warlock Features table.<\\/p><p style=\'margin-bottom: 15px; line-height: 1.6;\'>You can\'t pick the same invocation more than once unless its description says otherwise.<\\/p>\"},{\"level\":1,\"name\":\"Pact Magic\",\"description\":\"<p style=\'margin-bottom: 15px; line-height: 1.6;\'>Through occult ceremony, you have formed a pact with a mysterious entity to gain magical powers. The entity is a voice in the shadows—its identity unclear—but its boon to you is concrete: the ability to cast spells. See \\\"Spells\\\" for the rules on spellcasting. The information below details how you use those rules with Warlock spells, which appear in the Warlock spell list later in the class\'s description.<\\/p><p style=\'margin-bottom: 15px; line-height: 1.6;\'><em>Cantrips.<\\/em> You know two Warlock cantrips of your choice. <em>Eldritch Blast<\\/em> and <em>Prestidigitation<\\/em> are recommended. Whenever you gain a Warlock level, you can replace one of your cantrips from this feature with another Warlock cantrip of your choice.<\\/p><p style=\'margin-bottom: 15px; line-height: 1.6;\'>When you reach Warlock levels 4 and 10, you learn another Warlock cantrip of your choice, as shown in the Cantrips column of the Warlock Features table.<\\/p><p style=\'margin-bottom: 15px; line-height: 1.6;\'><em>Spell Slots.<\\/em> The Warlock Features table shows how many spell slots you have to cast your Warlock spells of levels 1–5. The table also shows the level of those slots, all of which are the same level. You regain all expended Pact Magic spell slots when you finish a Short or Long Rest.<\\/p><p style=\'margin-bottom: 15px; line-height: 1.6;\'>For example, when you\'re a level 5 Warlock, you have two level 3 spell slots. To cast the level 1 spell <em>Charm Person<\\/em>, you must spend one of those slots, and you cast it as a level 3 spell.<\\/p><p style=\'margin-bottom: 15px; line-height: 1.6;\'><em>Prepared Spells of Level 1+.<\\/em> You prepare the list of level 1+ spells that are available for you to cast with this feature. To start, choose two level 1 Warlock spells. <em>Charm Person<\\/em> and <em>Hex<\\/em> are recommended.<\\/p><p style=\'margin-bottom: 15px; line-height: 1.6;\'>The number of spells on your list increases as you gain Warlock levels, as shown in the Prepared Spells column of the Warlock Features table. Whenever that number increases, choose additional Warlock spells until the number of spells on your list matches the number in the table. The chosen spells must be of a level no higher than what\'s shown in the table\'s Slot Level column for your level. When you reach level 6, for example, you learn a new Warlock spell, which can be of levels 1–3.<\\/p><p style=\'margin-bottom: 15px; line-height: 1.6;\'>If another Warlock feature gives you spells that you always have prepared, those spells don\'t count against the number of spells you can prepare with this feature, but those spells otherwise count as Warlock spells for you.<\\/p><p style=\'margin-bottom: 15px; line-height: 1.6;\'><em>Changing Your Prepared Spells.<\\/em> Whenever you gain a Warlock level, you can replace one spell on your list with another Warlock spell of an eligible level.<\\/p><p style=\'margin-bottom: 15px; line-height: 1.6;\'><em>Spellcasting Ability.<\\/em> Charisma is the spellcasting ability for your Warlock spells.<\\/p><p style=\'margin-bottom: 15px; line-height: 1.6;\'><em>Spellcasting Focus.<\\/em> You can use an Arcane Focus as a Spellcasting Focus for your Warlock spells.<\\/p>\",\"modifiers\":[],\"desc\":\"<p style=\'margin-bottom: 15px; line-height: 1.6;\'>Through occult ceremony, you have formed a pact with a mysterious entity to gain magical powers. The entity is a voice in the shadows—its identity unclear—but its boon to you is concrete: the ability to cast spells. See \\\"Spells\\\" for the rules on spellcasting. The information below details how you use those rules with Warlock spells, which appear in the Warlock spell list later in the class\'s description.<\\/p><p style=\'margin-bottom: 15px; line-height: 1.6;\'><em>Cantrips.<\\/em> You know two Warlock cantrips of your choice. <em>Eldritch Blast<\\/em> and <em>Prestidigitation<\\/em> are recommended. Whenever you gain a Warlock level, you can replace one of your cantrips from this feature with another Warlock cantrip of your choice.<\\/p><p style=\'margin-bottom: 15px; line-height: 1.6;\'>When you reach Warlock levels 4 and 10, you learn another Warlock cantrip of your choice, as shown in the Cantrips column of the Warlock Features table.<\\/p><p style=\'margin-bottom: 15px; line-height: 1.6;\'><em>Spell Slots.<\\/em> The Warlock Features table shows how many spell slots you have to cast your Warlock spells of levels 1–5. The table also shows the level of those slots, all of which are the same level. You regain all expended Pact Magic spell slots when you finish a Short or Long Rest.<\\/p><p style=\'margin-bottom: 15px; line-height: 1.6;\'>For example, when you\'re a level 5 Warlock, you have two level 3 spell slots. To cast the level 1 spell <em>Charm Person<\\/em>, you must spend one of those slots, and you cast it as a level 3 spell.<\\/p><p style=\'margin-bottom: 15px; line-height: 1.6;\'><em>Prepared Spells of Level 1+.<\\/em> You prepare the list of level 1+ spells that are available for you to cast with this feature. To start, choose two level 1 Warlock spells. <em>Charm Person<\\/em> and <em>Hex<\\/em> are recommended.<\\/p><p style=\'margin-bottom: 15px; line-height: 1.6;\'>The number of spells on your list increases as you gain Warlock levels, as shown in the Prepared Spells column of the Warlock Features table. Whenever that number increases, choose additional Warlock spells until the number of spells on your list matches the number in the table. The chosen spells must be of a level no higher than what\'s shown in the table\'s Slot Level column for your level. When you reach level 6, for example, you learn a new Warlock spell, which can be of levels 1–3.<\\/p><p style=\'margin-bottom: 15px; line-height: 1.6;\'>If another Warlock feature gives you spells that you always have prepared, those spells don\'t count against the number of spells you can prepare with this feature, but those spells otherwise count as Warlock spells for you.<\\/p><p style=\'margin-bottom: 15px; line-height: 1.6;\'><em>Changing Your Prepared Spells.<\\/em> Whenever you gain a Warlock level, you can replace one spell on your list with another Warlock spell of an eligible level.<\\/p><p style=\'margin-bottom: 15px; line-height: 1.6;\'><em>Spellcasting Ability.<\\/em> Charisma is the spellcasting ability for your Warlock spells.<\\/p><p style=\'margin-bottom: 15px; line-height: 1.6;\'><em>Spellcasting Focus.<\\/em> You can use an Arcane Focus as a Spellcasting Focus for your Warlock spells.<\\/p>\"},{\"level\":2,\"name\":\"Magical Cunning\",\"description\":\"<p style=\'margin-bottom: 15px; line-height: 1.6;\'>You can perform an esoteric rite for 1 minute. At the end of it, you regain expended Pact Magic spell slots but no more than a number equal to half your maximum (round up). Once you use this feature, you can\'t do so again until you finish a Long Rest.<\\/p>\",\"modifiers\":[],\"desc\":\"<p style=\'margin-bottom: 15px; line-height: 1.6;\'>You can perform an esoteric rite for 1 minute. At the end of it, you regain expended Pact Magic spell slots but no more than a number equal to half your maximum (round up). Once you use this feature, you can\'t do so again until you finish a Long Rest.<\\/p>\"},{\"level\":3,\"name\":\"Subclass feature\",\"description\":\"<p style=\'margin-bottom: 15px; line-height: 1.6;\'>You gain a Warlock subclass of your choice. The Fiend Patron subclass is detailed after this class\'s description. A subclass is a specialization that grants you features at certain Warlock levels. For the rest of your career, you gain each of your subclass\'s features that are of your Warlock level or lower.<\\/p>\",\"modifiers\":[],\"desc\":\"<p style=\'margin-bottom: 15px; line-height: 1.6;\'>You gain a Warlock subclass of your choice. The Fiend Patron subclass is detailed after this class\'s description. A subclass is a specialization that grants you features at certain Warlock levels. For the rest of your career, you gain each of your subclass\'s features that are of your Warlock level or lower.<\\/p>\"},{\"level\":4,\"name\":\"Ability Score Improvement\",\"description\":\"<p style=\'margin-bottom: 15px; line-height: 1.6;\'>You gain the Ability Score Improvement feat (see \\\"Feats\\\") or another feat of your choice for which you qualify. You gain this feature again at Warlock levels 8, 12, and 16.<\\/p>\",\"modifiers\":[],\"desc\":\"<p style=\'margin-bottom: 15px; line-height: 1.6;\'>You gain the Ability Score Improvement feat (see \\\"Feats\\\") or another feat of your choice for which you qualify. You gain this feature again at Warlock levels 8, 12, and 16.<\\/p>\"},{\"level\":6,\"name\":\"Subclass feature\",\"description\":\"<p style=\'margin-bottom: 15px; line-height: 1.6;\'>You gain a feature from your Warlock subclass.<\\/p>\",\"modifiers\":[],\"desc\":\"<p style=\'margin-bottom: 15px; line-height: 1.6;\'>You gain a feature from your Warlock subclass.<\\/p>\"},{\"level\":8,\"name\":\"Ability Score Improvement\",\"description\":\"<p style=\'margin-bottom: 15px; line-height: 1.6;\'>You gain the Ability Score Improvement feat (see &quot;Feats&quot;) or another feat of your choice for which you qualify.<\\/p>\",\"modifiers\":[],\"desc\":\"<p style=\'margin-bottom: 15px; line-height: 1.6;\'>You gain the Ability Score Improvement feat (see &quot;Feats&quot;) or another feat of your choice for which you qualify.<\\/p>\"},{\"level\":9,\"name\":\"Contact Patron\",\"description\":\"<p style=\'margin-bottom: 15px; line-height: 1.6;\'>In the past, you usually contacted your patron through intermediaries. Now you can communicate directly; you always have the <em>Contact Other Plane<\\/em> spell prepared. With this feature, you can cast the spell without expending a spell slot to contact your patron, and you automatically succeed on the spell\'s saving throw.<\\/p><p style=\'margin-bottom: 15px; line-height: 1.6;\'>Once you cast the spell with this feature, you can\'t do so in this way again until you finish a Long Rest.<\\/p>\",\"modifiers\":[],\"desc\":\"<p style=\'margin-bottom: 15px; line-height: 1.6;\'>In the past, you usually contacted your patron through intermediaries. Now you can communicate directly; you always have the <em>Contact Other Plane<\\/em> spell prepared. With this feature, you can cast the spell without expending a spell slot to contact your patron, and you automatically succeed on the spell\'s saving throw.<\\/p><p style=\'margin-bottom: 15px; line-height: 1.6;\'>Once you cast the spell with this feature, you can\'t do so in this way again until you finish a Long Rest.<\\/p>\"},{\"level\":10,\"name\":\"Subclass feature\",\"description\":\"<p style=\'margin-bottom: 15px; line-height: 1.6;\'>You gain a feature from your Warlock subclass.<\\/p>\",\"modifiers\":[],\"desc\":\"<p style=\'margin-bottom: 15px; line-height: 1.6;\'>You gain a feature from your Warlock subclass.<\\/p>\"},{\"level\":11,\"name\":\"Mystic Arcanum (level 6 spell)\",\"description\":\"<p style=\'margin-bottom: 15px; line-height: 1.6;\'>Your patron grants you a magical secret called an arcanum. Choose one level 6 Warlock spell as this arcanum.<\\/p><p style=\'margin-bottom: 15px; line-height: 1.6;\'>You can cast your arcanum spell once without expending a spell slot, and you must finish a Long Rest before you can cast it in this way again.<\\/p><p style=\'margin-bottom: 15px; line-height: 1.6;\'>As shown in the Warlock Features table, you gain another Warlock spell of your choice that can be cast in this way when you reach Warlock levels 13 (level 7 spell), 15 (level 8 spell), and 17 (level 9 spell). You regain all uses of your Mystic Arcanum when you finish a Long Rest.<\\/p><p style=\'margin-bottom: 15px; line-height: 1.6;\'>Whenever you gain a Warlock level, you can replace one of your arcanum spells with another Warlock spell of the same level.<\\/p>\",\"modifiers\":[],\"desc\":\"<p style=\'margin-bottom: 15px; line-height: 1.6;\'>Your patron grants you a magical secret called an arcanum. Choose one level 6 Warlock spell as this arcanum.<\\/p><p style=\'margin-bottom: 15px; line-height: 1.6;\'>You can cast your arcanum spell once without expending a spell slot, and you must finish a Long Rest before you can cast it in this way again.<\\/p><p style=\'margin-bottom: 15px; line-height: 1.6;\'>As shown in the Warlock Features table, you gain another Warlock spell of your choice that can be cast in this way when you reach Warlock levels 13 (level 7 spell), 15 (level 8 spell), and 17 (level 9 spell). You regain all uses of your Mystic Arcanum when you finish a Long Rest.<\\/p><p style=\'margin-bottom: 15px; line-height: 1.6;\'>Whenever you gain a Warlock level, you can replace one of your arcanum spells with another Warlock spell of the same level.<\\/p>\"},{\"level\":12,\"name\":\"Ability Score Improvement\",\"description\":\"<p style=\'margin-bottom: 15px; line-height: 1.6;\'>You gain the Ability Score Improvement feat (see &quot;Feats&quot;) or another feat of your choice for which you qualify.<\\/p>\",\"modifiers\":[],\"desc\":\"<p style=\'margin-bottom: 15px; line-height: 1.6;\'>You gain the Ability Score Improvement feat (see &quot;Feats&quot;) or another feat of your choice for which you qualify.<\\/p>\"},{\"level\":13,\"name\":\"Mystic Arcanum (level 7 spell)\",\"description\":\"<p style=\'margin-bottom: 15px; line-height: 1.6;\'>At higher Warlock levels, you gain more Warlock spells of your choice that can be cast in this way.<\\/p>\",\"modifiers\":[],\"desc\":\"<p style=\'margin-bottom: 15px; line-height: 1.6;\'>At higher Warlock levels, you gain more Warlock spells of your choice that can be cast in this way.<\\/p>\"},{\"level\":14,\"name\":\"Subclass feature\",\"description\":\"<p style=\'margin-bottom: 15px; line-height: 1.6;\'>You gain a feature from your Warlock subclass.<\\/p>\",\"modifiers\":[],\"desc\":\"<p style=\'margin-bottom: 15px; line-height: 1.6;\'>You gain a feature from your Warlock subclass.<\\/p>\"},{\"level\":15,\"name\":\"Mystic Arcanum (level 8 spell)\",\"description\":\"<p style=\'margin-bottom: 15px; line-height: 1.6;\'>At higher Warlock levels, you gain more Warlock spells of your choice that can be cast in this way.<\\/p>\",\"modifiers\":[],\"desc\":\"<p style=\'margin-bottom: 15px; line-height: 1.6;\'>At higher Warlock levels, you gain more Warlock spells of your choice that can be cast in this way.<\\/p>\"},{\"level\":16,\"name\":\"Ability Score Improvement\",\"description\":\"<p style=\'margin-bottom: 15px; line-height: 1.6;\'>You gain the Ability Score Improvement feat (see &quot;Feats&quot;) or another feat of your choice for which you qualify.<\\/p>\",\"modifiers\":[],\"desc\":\"<p style=\'margin-bottom: 15px; line-height: 1.6;\'>You gain the Ability Score Improvement feat (see &quot;Feats&quot;) or another feat of your choice for which you qualify.<\\/p>\"},{\"level\":17,\"name\":\"Mystic Arcanum (level 9 spell)\",\"description\":\"<p style=\'margin-bottom: 15px; line-height: 1.6;\'>At higher Warlock levels, you gain more Warlock spells of your choice that can be cast in this way.<\\/p>\",\"modifiers\":[],\"desc\":\"<p style=\'margin-bottom: 15px; line-height: 1.6;\'>At higher Warlock levels, you gain more Warlock spells of your choice that can be cast in this way.<\\/p>\"},{\"level\":19,\"name\":\"Epic Boon\",\"description\":\"<p style=\'margin-bottom: 15px; line-height: 1.6;\'>You gain an Epic Boon feat (see \\\"Feats\\\") or another feat of your choice for which you qualify. Boon of Fate is recommended.<\\/p>\",\"modifiers\":[],\"desc\":\"<p style=\'margin-bottom: 15px; line-height: 1.6;\'>You gain an Epic Boon feat (see \\\"Feats\\\") or another feat of your choice for which you qualify. Boon of Fate is recommended.<\\/p>\"},{\"level\":20,\"name\":\"Eldritch Master\",\"description\":\"<p style=\'margin-bottom: 15px; line-height: 1.6;\'>When you use your Magical Cunning feature, you regain all your expended Pact Magic spell slots.<\\/p>\",\"collapsible_content\":\"<p style=\'margin-bottom: 15px; line-height: 1.6;\'><h3>Eldritch Invocation Options<\\/h3><\\/p><p style=\'margin-bottom: 15px; line-height: 1.6;\'>Eldritch Invocation options appear in alphabetical order.<\\/p><h4 style=\'margin-top: 15px; margin-bottom: 5px; color: #711a19;\'>Agonizing Blast<\\/h4><p style=\'margin-bottom: 15px; line-height: 1.6;\'><em>Prerequisite: Level 2+ Warlock, a Warlock Cantrip That Deals Damage<\\/em><\\/p><p style=\'margin-bottom: 15px; line-height: 1.6;\'>Choose one of your known Warlock cantrips that deals damage. You can add your Charisma modifier to that spell\'s damage rolls.<\\/p><p style=\'margin-bottom: 15px; line-height: 1.6;\'><em>Repeatable.<\\/em> You can gain this invocation more than once. Each time you do so, choose a different eligible cantrip.<\\/p><h4 style=\'margin-top: 15px; margin-bottom: 5px; color: #711a19;\'>Armor of Shadows<\\/h4><p style=\'margin-bottom: 15px; line-height: 1.6;\'>You can cast <em>Mage Armor<\\/em> on yourself without expending a spell slot.<\\/p><h4 style=\'margin-top: 15px; margin-bottom: 5px; color: #711a19;\'>Ascendant Step<\\/h4><p style=\'margin-bottom: 15px; line-height: 1.6;\'><em>Prerequisite: Level 5+ Warlock<\\/em><\\/p><p style=\'margin-bottom: 15px; line-height: 1.6;\'>You can cast <em>Levitate<\\/em> on yourself without expending a spell slot.<\\/p><h4 style=\'margin-top: 15px; margin-bottom: 5px; color: #711a19;\'>Devil\'s Sight<\\/h4><p style=\'margin-bottom: 15px; line-height: 1.6;\'><em>Prerequisite: Level 2+ Warlock<\\/em><\\/p><p style=\'margin-bottom: 15px; line-height: 1.6;\'>You can see normally in Dim Light and Darkness—both magical and nonmagical—within 120 feet of yourself.<\\/p><h4 style=\'margin-top: 15px; margin-bottom: 5px; color: #711a19;\'>Devouring Blade<\\/h4><p style=\'margin-bottom: 15px; line-height: 1.6;\'><em>Prerequisite: Level 12+ Warlock, Thirsting Blade Invocation<\\/em><\\/p><p style=\'margin-bottom: 15px; line-height: 1.6;\'>The Extra Attack of your Thirsting Blade invocation confers two extra attacks rather than one.<\\/p><h4 style=\'margin-top: 15px; margin-bottom: 5px; color: #711a19;\'>Eldritch Mind<\\/h4><p style=\'margin-bottom: 15px; line-height: 1.6;\'>You have Advantage on Constitution saving throws that you make to maintain Concentration.<\\/p><h4 style=\'margin-top: 15px; margin-bottom: 5px; color: #711a19;\'>Eldritch Smite<\\/h4><p style=\'margin-bottom: 15px; line-height: 1.6;\'><em>Prerequisite: Level 5+ Warlock, Pact of the Blade Invocation<\\/em><\\/p><p style=\'margin-bottom: 15px; line-height: 1.6;\'>Once per turn when you hit a creature with your pact weapon, you can expend a Pact Magic spell slot to deal an extra 1d8 Force damage to the target,\\nplus another 1d8 per level of the spell slot, and you can give the target the Prone condition if it is Huge or smaller.<\\/p><h4 style=\'margin-top: 15px; margin-bottom: 5px; color: #711a19;\'>Eldritch Spear<\\/h4><p style=\'margin-bottom: 15px; line-height: 1.6;\'><em>Prerequisite: Level 2+ Warlock, a Warlock Cantrip That Deals Damage<\\/em><\\/p><p style=\'margin-bottom: 15px; line-height: 1.6;\'>Choose one of your known Warlock cantrips that deals damage and has a range of 10+ feet. When you cast that spell, its range increases by a number of feet equal to 30 times your Warlock level.<\\/p><p style=\'margin-bottom: 15px; line-height: 1.6;\'><em>Repeatable.<\\/em> You can gain this invocation more than once. Each time you do so, choose a different eligible cantrip.<\\/p><h4 style=\'margin-top: 15px; margin-bottom: 5px; color: #711a19;\'>Fiendish Vigor<\\/h4><p style=\'margin-bottom: 15px; line-height: 1.6;\'><em>Prerequisite: Level 2+ Warlock<\\/em><\\/p><p style=\'margin-bottom: 15px; line-height: 1.6;\'>You can cast <em>False Life<\\/em> on yourself without expending a spell slot. When you cast the spell with this feature, you don\'t roll the die for the Temporary Hit Points; you automatically get the highest number on the die.<\\/p><h4 style=\'margin-top: 15px; margin-bottom: 5px; color: #711a19;\'>Gaze of Two Minds<\\/h4><p style=\'margin-bottom: 15px; line-height: 1.6;\'><em>Prerequisite: Level 5+ Warlock<\\/em><\\/p><p style=\'margin-bottom: 15px; line-height: 1.6;\'>You can use a Bonus Action to touch a willing creature and perceive through its senses until the end of your next turn. As long as the creature is on the same plane of existence as you, you can take a Bonus Action on subsequent turns to maintain this connection, extending the duration until the end of your next turn. The connection ends if you don\'t maintain it in this way.<\\/p><p style=\'margin-bottom: 15px; line-height: 1.6;\'>While perceiving through the other creature\'s senses, you benefit from any special senses possessed by that creature, and you can cast spells as if you were in your space or the other creature\'s space if the two of you are within 60 feet of each other.<\\/p><h4 style=\'margin-top: 15px; margin-bottom: 5px; color: #711a19;\'>Gift of the Depths<\\/h4><p style=\'margin-bottom: 15px; line-height: 1.6;\'><em>Prerequisite: Level 5+ Warlock<\\/em><\\/p><p style=\'margin-bottom: 15px; line-height: 1.6;\'>You can breathe underwater, and you gain a Swim Speed equal to your Speed.<\\/p><p style=\'margin-bottom: 15px; line-height: 1.6;\'>You can also cast <em>Water Breathing<\\/em> once without expending a spell slot. You regain the ability to cast it in this way again when you finish a Long Rest.<\\/p><h4 style=\'margin-top: 15px; margin-bottom: 5px; color: #711a19;\'>Gift of the Protectors<\\/h4><p style=\'margin-bottom: 15px; line-height: 1.6;\'><em>Prerequisite: Level 9+ Warlock, Pact of the Tome Invocation<\\/em><\\/p><p style=\'margin-bottom: 15px; line-height: 1.6;\'>A new page appears in your <em>Book of Shadows<\\/em> when you conjure it. With your permission, a creature can take an action to write its name on that page, which can contain a number of names equal to your Charisma modifier (minimum of one name).<\\/p><p style=\'margin-bottom: 15px; line-height: 1.6;\'>When any creature whose name is on the page is reduced to 0 Hit Points but not killed outright, the creature magically drops to 1 Hit Point instead. Once this magic is triggered, no creature can benefit from it until you finish a Long Rest.<\\/p><p style=\'margin-bottom: 15px; line-height: 1.6;\'>As a Magic action, you can erase a name on the page by touching it.<\\/p><h4 style=\'margin-top: 15px; margin-bottom: 5px; color: #711a19;\'>Investment of the Chain Master<\\/h4><p style=\'margin-bottom: 15px; line-height: 1.6;\'><em>Prerequisite: Level 5+ Warlock, Pact of the Chain Invocation<\\/em><\\/p><p style=\'margin-bottom: 15px; line-height: 1.6;\'>When you cast <em>Find Familiar<\\/em>, you infuse the summoned familiar with a measure of your eldritch power, granting the creature the following benefits.<\\/p><p style=\'margin-bottom: 15px; line-height: 1.6;\'><em>Aerial or Aquatic.<\\/em> The familiar gains either a Fly Speed or a Swim Speed (your choice) of 40 feet.<\\/p><p style=\'margin-bottom: 15px; line-height: 1.6;\'><em>Quick Attack.<\\/em> As a Bonus Action, you can command the familiar to take the Attack action.<\\/p><p style=\'margin-bottom: 15px; line-height: 1.6;\'><em>Necrotic or Radiant Damage.<\\/em> Whenever the familiar deals Bludgeoning, Piercing, or Slashing damage, you can make it deal Necrotic or Radiant damage instead.<\\/p><p style=\'margin-bottom: 15px; line-height: 1.6;\'><em>Your Save DC.<\\/em> If the familiar forces a creature to make a saving throw, it uses your spell save DC.<\\/p><p style=\'margin-bottom: 15px; line-height: 1.6;\'><em>Resistance.<\\/em> When the familiar takes damage, you can take a Reaction to grant it Resistance against that damage.<\\/p><h4 style=\'margin-top: 15px; margin-bottom: 5px; color: #711a19;\'>Lessons of the First Ones<\\/h4><p style=\'margin-bottom: 15px; line-height: 1.6;\'><em>Prerequisite: Level 2+ Warlock<\\/em><\\/p><p style=\'margin-bottom: 15px; line-height: 1.6;\'>You have received knowledge from an elder entity of the multiverse, allowing you to gain one Origin feat of your choice (see \\\"Feats\\\").<\\/p><p style=\'margin-bottom: 15px; line-height: 1.6;\'><em>Repeatable.<\\/em> You can gain this invocation more than once. Each time you do so, choose a different Origin feat.<\\/p><h4 style=\'margin-top: 15px; margin-bottom: 5px; color: #711a19;\'>Lifedrinker<\\/h4><p style=\'margin-bottom: 15px; line-height: 1.6;\'><em>Prerequisite: Level 9+ Warlock, Pact of the Blade Invocation<\\/em><\\/p><p style=\'margin-bottom: 15px; line-height: 1.6;\'>Once per turn when you hit a creature with your pact weapon, you can deal an extra 1d6 Necrotic, Psychic, or Radiant damage (your choice) to the creature, and you can expend one of your Hit Point Dice to roll it and regain a number of Hit Points equal to the roll plus your Constitution modifier (minimum of 1 Hit Point).<\\/p><h4 style=\'margin-top: 15px; margin-bottom: 5px; color: #711a19;\'>Mask of Many Faces<\\/h4><p style=\'margin-bottom: 15px; line-height: 1.6;\'><em>Prerequisite: Level 2+ Warlock<\\/em><\\/p><p style=\'margin-bottom: 15px; line-height: 1.6;\'>You can cast <em>Disguise Self<\\/em> without expending a spell slot.<\\/p><h4 style=\'margin-top: 15px; margin-bottom: 5px; color: #711a19;\'>Master of Myriad Forms<\\/h4><p style=\'margin-bottom: 15px; line-height: 1.6;\'><em>Prerequisite: Level 5+ Warlock<\\/em><\\/p><p style=\'margin-bottom: 15px; line-height: 1.6;\'>You can cast <em>Alter Self<\\/em> without expending a spell slot.<\\/p><h4 style=\'margin-top: 15px; margin-bottom: 5px; color: #711a19;\'>Misty Visions<\\/h4><p style=\'margin-bottom: 15px; line-height: 1.6;\'><em>Prerequisite: Level 2+ Warlock<\\/em><\\/p><p style=\'margin-bottom: 15px; line-height: 1.6;\'>You can cast <em>Silent Image<\\/em> without expending a spell slot.<\\/p><h4 style=\'margin-top: 15px; margin-bottom: 5px; color: #711a19;\'>One with Shadows<\\/h4><p style=\'margin-bottom: 15px; line-height: 1.6;\'><em>Prerequisite: Level 5+ Warlock<\\/em><\\/p><p style=\'margin-bottom: 15px; line-height: 1.6;\'>While you\'re in an area of Dim Light or Darkness, you can cast <em>Invisibility<\\/em> on yourself without expending a spell slot.<\\/p><h4 style=\'margin-top: 15px; margin-bottom: 5px; color: #711a19;\'>Otherworldly Leap<\\/h4><p style=\'margin-bottom: 15px; line-height: 1.6;\'><em>Prerequisite: Level 2+ Warlock<\\/em><\\/p><p style=\'margin-bottom: 15px; line-height: 1.6;\'>You can cast <em>Jump<\\/em> on yourself without expending a spell slot.<\\/p><h4 style=\'margin-top: 15px; margin-bottom: 5px; color: #711a19;\'>Pact of the Blade<\\/h4><p style=\'margin-bottom: 15px; line-height: 1.6;\'>As a Bonus Action, you can conjure a pact weapon in your hand—a Simple or Martial Melee weapon of your choice with which you bond—or create a bond with a magic weapon you touch; you can\'t bond with a magic weapon if someone else is attuned to it or another Warlock is bonded with it. Until the bond ends, you have proficiency with the weapon, and you can use it as a Spellcasting Focus.<\\/p><p style=\'margin-bottom: 15px; line-height: 1.6;\'>Whenever you attack with the bonded weapon, you can use your Charisma modifier for the attack and damage rolls instead of using Strength or Dexterity; and you can cause the weapon to deal Necrotic, Psychic, or Radiant damage or its normal damage type.<\\/p><p style=\'margin-bottom: 15px; line-height: 1.6;\'>Your bond with the weapon ends if you use this feature\'s Bonus Action again, if the weapon is more than 5 feet away from you for 1 minute or more, or if you die. A conjured weapon disappears when the bond ends.<\\/p><h4 style=\'margin-top: 15px; margin-bottom: 5px; color: #711a19;\'>Pact of the Chain<\\/h4><p style=\'margin-bottom: 15px; line-height: 1.6;\'>You learn the <em>Find Familiar<\\/em> spell and can cast it as a Magic action without expending a spell slot.<\\/p><p style=\'margin-bottom: 15px; line-height: 1.6;\'>When you cast the spell, you choose one of the normal forms for your familiar or one of the following special forms: <strong>Imp, Pseudodragon, Quasit, Skeleton, Sphinx of Wonder, Sprite,<\\/strong> or <strong>Venomous Snake<\\/strong> (see \\\"Monsters\\\" for the familiar\'s stat block).<\\/p><p style=\'margin-bottom: 15px; line-height: 1.6;\'>Additionally, when you take the Attack action, you can forgo one of your own attacks to allow your familiar to make one attack of its own with its Reaction.<\\/p><h4 style=\'margin-top: 15px; margin-bottom: 5px; color: #711a19;\'>Pact of the Tome<\\/h4><p style=\'margin-bottom: 15px; line-height: 1.6;\'>Stitching together strands of shadow, you conjure forth a book in your hand at the end of a Short or Long Rest. This <em>Book of Shadows<\\/em> (you determine its appearance) contains eldritch magic that only you can access, granting you the benefits below. The book disappears if you conjure another book with this feature or if you die.<\\/p><p style=\'margin-bottom: 15px; line-height: 1.6;\'><em>Cantrips and Rituals.<\\/em> When the book appears, choose three cantrips, and choose two level 1 spells that have the Ritual tag. The spells can be from any class\'s spell list, and they must be spells you don\'t already have prepared. While the book is on your person, you have the chosen spells prepared, and they function as Warlock spells for you.<\\/p><p style=\'margin-bottom: 15px; line-height: 1.6;\'><em>Spellcasting Focus.<\\/em> You can use the book as a Spellcasting Focus.<\\/p><h4 style=\'margin-top: 15px; margin-bottom: 5px; color: #711a19;\'>Repelling Blast<\\/h4><p style=\'margin-bottom: 15px; line-height: 1.6;\'><em>Prerequisite: Level 2+ Warlock, a Warlock Cantrip That Deals Damage via an Attack Roll<\\/em><\\/p><p style=\'margin-bottom: 15px; line-height: 1.6;\'>Choose one of your known Warlock cantrips that requires an attack roll. When you hit a Large or smaller creature with that cantrip, you can push the creature up to 10 feet straight away from you.<\\/p><p style=\'margin-bottom: 15px; line-height: 1.6;\'><em>Repeatable.<\\/em> You can gain this invocation more than once. Each time you do so, choose a different eligible cantrip.<\\/p><h4 style=\'margin-top: 15px; margin-bottom: 5px; color: #711a19;\'>Thirsting Blade<\\/h4><p style=\'margin-bottom: 15px; line-height: 1.6;\'><em>Prerequisite: Level 5+ Warlock, Pact of the Blade Invocation<\\/em><\\/p><p style=\'margin-bottom: 15px; line-height: 1.6;\'>You gain the Extra Attack feature for your pact weapon only. With that feature, you can attack twice with the weapon instead of once when you take the Attack action on your turn.<\\/p><h4 style=\'margin-top: 15px; margin-bottom: 5px; color: #711a19;\'>Visions of Distant Realms<\\/h4><p style=\'margin-bottom: 15px; line-height: 1.6;\'><em>Prerequisite: Level 9+ Warlock<\\/em><\\/p><p style=\'margin-bottom: 15px; line-height: 1.6;\'>You can cast <em>Arcane Eye<\\/em> without expending a spell slot.<\\/p><h4 style=\'margin-top: 15px; margin-bottom: 5px; color: #711a19;\'>Whispers of the Grave<\\/h4><p style=\'margin-bottom: 15px; line-height: 1.6;\'><em>Prerequisite: Level 7+ Warlock<\\/em><\\/p><p style=\'margin-bottom: 15px; line-height: 1.6;\'>You can cast <em>Speak with Dead<\\/em> without expending a spell slot.<\\/p><h4 style=\'margin-top: 15px; margin-bottom: 5px; color: #711a19;\'>Witch Sight<\\/h4><p style=\'margin-bottom: 15px; line-height: 1.6;\'><em>Prerequisite: Level 15+ Warlock<\\/em><\\/p><p style=\'margin-bottom: 15px; line-height: 1.6;\'>You have Truesight with a range of 30 feet.<\\/p>\",\"modifiers\":[],\"desc\":\"<p style=\'margin-bottom: 15px; line-height: 1.6;\'>When you use your Magical Cunning feature, you regain all your expended Pact Magic spell slots.<\\/p>\"}]', '[{\"level\":1,\"prof_bonus\":2,\"class_specific\":{\"invocations\":\"1\",\"cantrips\":\"2\",\"prepared_spells\":\"2\",\"slots\":\"1\",\"slot_level\":\"1\"}},{\"level\":2,\"prof_bonus\":2,\"class_specific\":{\"invocations\":\"3\",\"cantrips\":\"2\",\"prepared_spells\":\"3\",\"slots\":\"2\",\"slot_level\":\"1\"}},{\"level\":3,\"prof_bonus\":2,\"class_specific\":{\"invocations\":\"3\",\"cantrips\":\"2\",\"prepared_spells\":\"4\",\"slots\":\"2\",\"slot_level\":\"2\"}},{\"level\":4,\"prof_bonus\":2,\"class_specific\":{\"invocations\":\"3\",\"cantrips\":\"3\",\"prepared_spells\":\"5\",\"slots\":\"2\",\"slot_level\":\"2\"}},{\"level\":5,\"prof_bonus\":3,\"class_specific\":{\"invocations\":\"5\",\"cantrips\":\"3\",\"prepared_spells\":\"6\",\"slots\":\"2\",\"slot_level\":\"3\"}},{\"level\":6,\"prof_bonus\":3,\"class_specific\":{\"invocations\":\"5\",\"cantrips\":\"3\",\"prepared_spells\":\"7\",\"slots\":\"2\",\"slot_level\":\"3\"}},{\"level\":7,\"prof_bonus\":3,\"class_specific\":{\"invocations\":\"6\",\"cantrips\":\"3\",\"prepared_spells\":\"8\",\"slots\":\"2\",\"slot_level\":\"4\"}},{\"level\":8,\"prof_bonus\":3,\"class_specific\":{\"invocations\":\"6\",\"cantrips\":\"3\",\"prepared_spells\":\"9\",\"slots\":\"2\",\"slot_level\":\"4\"}},{\"level\":9,\"prof_bonus\":4,\"class_specific\":{\"invocations\":\"7\",\"cantrips\":\"3\",\"prepared_spells\":\"10\",\"slots\":\"2\",\"slot_level\":\"5\"}},{\"level\":10,\"prof_bonus\":4,\"class_specific\":{\"invocations\":\"7\",\"cantrips\":\"4\",\"prepared_spells\":\"10\",\"slots\":\"2\",\"slot_level\":\"5\"}},{\"level\":11,\"prof_bonus\":4,\"class_specific\":{\"invocations\":\"7\",\"cantrips\":\"4\",\"prepared_spells\":\"11\",\"slots\":\"3\",\"slot_level\":\"5\"}},{\"level\":12,\"prof_bonus\":4,\"class_specific\":{\"invocations\":\"8\",\"cantrips\":\"4\",\"prepared_spells\":\"11\",\"slots\":\"3\",\"slot_level\":\"5\"}},{\"level\":13,\"prof_bonus\":5,\"class_specific\":{\"invocations\":\"8\",\"cantrips\":\"4\",\"prepared_spells\":\"12\",\"slots\":\"3\",\"slot_level\":\"5\"}},{\"level\":14,\"prof_bonus\":5,\"class_specific\":{\"invocations\":\"8\",\"cantrips\":\"4\",\"prepared_spells\":\"12\",\"slots\":\"3\",\"slot_level\":\"5\"}},{\"level\":15,\"prof_bonus\":5,\"class_specific\":{\"invocations\":\"9\",\"cantrips\":\"4\",\"prepared_spells\":\"13\",\"slots\":\"3\",\"slot_level\":\"5\"}},{\"level\":16,\"prof_bonus\":5,\"class_specific\":{\"invocations\":\"9\",\"cantrips\":\"4\",\"prepared_spells\":\"13\",\"slots\":\"3\",\"slot_level\":\"5\"}},{\"level\":17,\"prof_bonus\":6,\"class_specific\":{\"invocations\":\"9\",\"cantrips\":\"4\",\"prepared_spells\":\"14\",\"slots\":\"4\",\"slot_level\":\"5\"}},{\"level\":18,\"prof_bonus\":6,\"class_specific\":{\"invocations\":\"10\",\"cantrips\":\"4\",\"prepared_spells\":\"14\",\"slots\":\"4\",\"slot_level\":\"5\"}},{\"level\":19,\"prof_bonus\":6,\"class_specific\":{\"invocations\":\"10\",\"cantrips\":\"4\",\"prepared_spells\":\"15\",\"slots\":\"4\",\"slot_level\":\"5\"}},{\"level\":20,\"prof_bonus\":6,\"class_specific\":{\"invocations\":\"10\",\"cantrips\":\"4\",\"prepared_spells\":\"15\",\"slots\":\"4\",\"slot_level\":\"5\"}}]', '{\"primary_ability\":\"Charisma\",\"hit_point_die\":\"D8 per Warlock level\",\"saving_throws\":[\"Wisdom\",\"Charisma\"],\"skills\":{\"choose\":2,\"options\":[\"Arcana\",\"Deception\",\"Hist\",\"y\",\"Intimidation\",\"Investigation\",\"Nature\",\"Religion\"]},\"weapon_proficiencies\":[\"Simple weapons\"],\"armor_training\":[\"Light armor\"],\"starting_equipment\":\"Choose A or B: (A) Leather Armor, Sickle, 2 Daggers, Arcane Focus (orb), Book (occult lore), Scholar\'s Pack, and 15 GP; or (B) 100 GP\"}', '[\"arcane-gate\",\"astral-projection\",\"banishment\",\"befuddlement\",\"blade-ward\",\"blight\",\"charm-person\",\"chill-touch\",\"circle-of-death\",\"conjure-fey\",\"contact-other-plane\",\"counterspell\",\"create-undead\",\"darkness\",\"demiplane\",\"detect-magic\",\"dimension-door\",\"dispel-magic\",\"dominate-monster\",\"dream\",\"eldritch-blast\",\"enthrall\",\"etherealness\",\"expeditious-retreat\",\"eyebite\",\"fear\",\"feeblemind\",\"finger-of-death\",\"flesh-to-stone\",\"fly\",\"forcecage\",\"foresight\",\"gaseous-form\",\"glibness\",\"hallucinatory-terrain\",\"hold-monster\",\"hold-person\",\"hypnotic-pattern\",\"illusory-script\",\"imprisonment\",\"invisibility\",\"mage-hand\",\"magic-circle\",\"major-image\",\"mass-suggestion\",\"minor-illusion\",\"misty-step\",\"plane-shift\",\"poison-spray\",\"power-word-kill\",\"power-word-stun\",\"protection-from-evil-and-good\",\"ray-of-enfeeblement\",\"remove-curse\",\"scrying\",\"shatter\",\"spider-climb\",\"suggestion\",\"tongues\",\"true-polymorph\",\"true-seeing\",\"true-strike\",\"vampiric-touch\",\"weird\"]', 0, NULL, NULL);
INSERT INTO `classes` (`class_id`, `class_name`, `hit_die`, `primary_ability`, `class_desc`, `hit_points`, `proficiencies`, `equipment`, `becoming`, `multiclassing`, `srd_source`, `features`, `level_progression`, `core_traits`, `spell_list`, `is_homebrew`, `author_id`, `deleted_at`) VALUES
('wizard', 'Wizard', 6, 'Intelligence', '<p>A scholarly magic-user capable of manipulating the structures of reality. Wizards are supreme magic-users, defined and united as a class by the spells they cast.</p>', '{\"logic\":{\"die_sides\":6,\"base\":6,\"average\":4,\"stat_modifier\":\"Constitution\"},\"display\":{\"hit_dice\":\"1d6 per Wizard level\",\"hp_at_level_1\":\"6 + your Constitution modifier\",\"hp_higher_levels\":\"1d6 (or 4) + your Constitution modifier per Wizard level after 1st\"}}', '{\"granted\":{\"armor\":[],\"weapons\":[\"Simple weapons\"],\"tools\":[],\"saving_throws\":[\"Intelligence\",\"Wisdom\"]},\"choices\":[{\"type\":\"skills\",\"choose\":2,\"options\":[\"Arcana\",\"History\",\"Insight\",\"Investigation\",\"Medicine\",\"Nature\",\"Religion\"]}],\"display\":{\"skills\":\"Choose 2: Arcana, History, Insight, Investigation, Medicine, Nature, or Religion\"}}', '[\"2 Daggers\",\"Arcane Focus\",\"Robe\",\"Spellbook\",\"Scholar\'s Pack\",\"5 GP\"]', NULL, '{\"requirements\":\"Intelligence 13+\",\"proficiencies_gained\":[\"None\"]}', 'SRD 5.2.1, Page 90', '[{\"level\":1,\"name\":\"Spellcasting\",\"description\":\"<p style=\'margin-bottom: 15px; line-height: 1.6;\'>As a student of arcane magic, you have learned to cast spells. See \\\"Spells\\\" for the rules on spellcasting. The information below details how you use those rules with Wizard spells, which appear in the Wizard spell list later in the class\'s description.<\\/p>\\n<p style=\'margin-bottom: 15px; line-height: 1.6;\'><strong>Cantrips.<\\/strong> You know three Wizard cantrips of your choice. <strong>Light<\\/strong>, <strong>Mage Hand<\\/strong>, and <strong>Ray of Frost<\\/strong> are recommended. Whenever you finish a Long Rest, you can replace one of your cantrips from this feature with another Wizard cantrip of your choice.<\\/p>\\n<p style=\'margin-bottom: 15px; line-height: 1.6;\'>When you reach Wizard levels 4 and 10, you learn another Wizard cantrip of your choice, as shown in the Cantrips column of the Wizard Features table.<\\/p>\\n<p style=\'margin-bottom: 15px; line-height: 1.6;\'><strong>Spellbook.<\\/strong> Your wizardly apprenticeship culminated in the creation of a unique book: your spellbook. It is a Tiny object that weighs 3 pounds, contains 100 pages, and can be read only by you or someone casting <strong>Identify<\\/strong>. You determine the book\'s appearance and materials, such as a gilt-edged tome or a collection of vellum bound with twine.<\\/p>\\n<p style=\'margin-bottom: 15px; line-height: 1.6;\'>The book contains the level 1+ spells you know. It starts with six level 1 Wizard spells of your choice. <strong>Detect Magic<\\/strong>, <strong>Feather Fall<\\/strong>, <strong>Mage Armor<\\/strong>, <strong>Magic Missile<\\/strong>, <strong>Sleep<\\/strong>, and <strong>Thunderwave<\\/strong> are recommended.<\\/p>\\n<p style=\'margin-bottom: 15px; line-height: 1.6;\'>Whenever you gain a Wizard level after 1, add two Wizard spells of your choice to your spellbook. Each of these spells must be of a level for which you have spell slots, as shown in the Wizard Features table. The spells are the culmination of arcane research you do regularly.<\\/p>\\n<p style=\'margin-bottom: 15px; line-height: 1.6;\'><strong>Spell Slots.<\\/strong> The Wizard Features table shows how many spell slots you have to cast your level 1+ spells. You regain all expended slots when you finish a Long Rest.<\\/p>\\n<p style=\'margin-bottom: 15px; line-height: 1.6;\'><strong>Prepared Spells of Level 1+.<\\/strong> You prepare the list of level 1+ spells that are available for you to cast with this feature. To do so, choose four spells from your spellbook. The chosen spells must be of a level for which you have spell slots.<\\/p>\\n<p style=\'margin-bottom: 15px; line-height: 1.6;\'>The number of spells on your list increases as you gain Wizard levels, as shown in the Prepared Spells column of the Wizard Features table. Whenever that number increases, choose additional Wizard spells until the number of spells on your list matches the number in the table. The chosen spells must be of a level for which you have spell slots. For example, if you\'re a level 3 Wizard, your list of prepared spells can include six spells of levels 1 and 2 in any combination, chosen from your spellbook.<\\/p>\\n<p style=\'margin-bottom: 15px; line-height: 1.6;\'>If another Wizard feature gives you spells that you always have prepared, those spells don\'t count against the number of spells you can prepare with this feature, but those spells otherwise count as Wizard spells for you.<\\/p>\\n<p style=\'margin-bottom: 15px; line-height: 1.6;\'><strong>Changing Your Prepared Spells.<\\/strong> Whenever you finish a Long Rest, you can change your list of prepared spells, replacing any of the spells there with spells from your spellbook.<\\/p>\\n<p style=\'margin-bottom: 15px; line-height: 1.6;\'><strong>Spellcasting Ability.<\\/strong> Intelligence is your spellcasting ability for your Wizard spells.<\\/p>\\n<p style=\'margin-bottom: 15px; line-height: 1.6;\'><strong>Spellcasting Focus.<\\/strong> You can use an Arcane Focus or your spellbook as a Spellcasting Focus for your Wizard spells.<\\/p>\",\"mechanics\":null,\"modifiers\":[],\"desc\":\"<p style=\'margin-bottom: 15px; line-height: 1.6;\'>As a student of arcane magic, you have learned to cast spells. See \\\"Spells\\\" for the rules on spellcasting. The information below details how you use those rules with Wizard spells, which appear in the Wizard spell list later in the class\'s description.<\\/p>\\n<p style=\'margin-bottom: 15px; line-height: 1.6;\'><strong>Cantrips.<\\/strong> You know three Wizard cantrips of your choice. <strong>Light<\\/strong>, <strong>Mage Hand<\\/strong>, and <strong>Ray of Frost<\\/strong> are recommended. Whenever you finish a Long Rest, you can replace one of your cantrips from this feature with another Wizard cantrip of your choice.<\\/p>\\n<p style=\'margin-bottom: 15px; line-height: 1.6;\'>When you reach Wizard levels 4 and 10, you learn another Wizard cantrip of your choice, as shown in the Cantrips column of the Wizard Features table.<\\/p>\\n<p style=\'margin-bottom: 15px; line-height: 1.6;\'><strong>Spellbook.<\\/strong> Your wizardly apprenticeship culminated in the creation of a unique book: your spellbook. It is a Tiny object that weighs 3 pounds, contains 100 pages, and can be read only by you or someone casting <strong>Identify<\\/strong>. You determine the book\'s appearance and materials, such as a gilt-edged tome or a collection of vellum bound with twine.<\\/p>\\n<p style=\'margin-bottom: 15px; line-height: 1.6;\'>The book contains the level 1+ spells you know. It starts with six level 1 Wizard spells of your choice. <strong>Detect Magic<\\/strong>, <strong>Feather Fall<\\/strong>, <strong>Mage Armor<\\/strong>, <strong>Magic Missile<\\/strong>, <strong>Sleep<\\/strong>, and <strong>Thunderwave<\\/strong> are recommended.<\\/p>\\n<p style=\'margin-bottom: 15px; line-height: 1.6;\'>Whenever you gain a Wizard level after 1, add two Wizard spells of your choice to your spellbook. Each of these spells must be of a level for which you have spell slots, as shown in the Wizard Features table. The spells are the culmination of arcane research you do regularly.<\\/p>\\n<p style=\'margin-bottom: 15px; line-height: 1.6;\'><strong>Spell Slots.<\\/strong> The Wizard Features table shows how many spell slots you have to cast your level 1+ spells. You regain all expended slots when you finish a Long Rest.<\\/p>\\n<p style=\'margin-bottom: 15px; line-height: 1.6;\'><strong>Prepared Spells of Level 1+.<\\/strong> You prepare the list of level 1+ spells that are available for you to cast with this feature. To do so, choose four spells from your spellbook. The chosen spells must be of a level for which you have spell slots.<\\/p>\\n<p style=\'margin-bottom: 15px; line-height: 1.6;\'>The number of spells on your list increases as you gain Wizard levels, as shown in the Prepared Spells column of the Wizard Features table. Whenever that number increases, choose additional Wizard spells until the number of spells on your list matches the number in the table. The chosen spells must be of a level for which you have spell slots. For example, if you\'re a level 3 Wizard, your list of prepared spells can include six spells of levels 1 and 2 in any combination, chosen from your spellbook.<\\/p>\\n<p style=\'margin-bottom: 15px; line-height: 1.6;\'>If another Wizard feature gives you spells that you always have prepared, those spells don\'t count against the number of spells you can prepare with this feature, but those spells otherwise count as Wizard spells for you.<\\/p>\\n<p style=\'margin-bottom: 15px; line-height: 1.6;\'><strong>Changing Your Prepared Spells.<\\/strong> Whenever you finish a Long Rest, you can change your list of prepared spells, replacing any of the spells there with spells from your spellbook.<\\/p>\\n<p style=\'margin-bottom: 15px; line-height: 1.6;\'><strong>Spellcasting Ability.<\\/strong> Intelligence is your spellcasting ability for your Wizard spells.<\\/p>\\n<p style=\'margin-bottom: 15px; line-height: 1.6;\'><strong>Spellcasting Focus.<\\/strong> You can use an Arcane Focus or your spellbook as a Spellcasting Focus for your Wizard spells.<\\/p>\"},{\"level\":1,\"name\":\"Ritual Adept\",\"description\":\"<p style=\'margin-bottom: 15px; line-height: 1.6;\'>You can cast any spell as a Ritual if that spell has the Ritual tag and the spell is in your spellbook. You needn\'t have the spell prepared, but you must read from the book to cast a spell in this way.<\\/p>\",\"mechanics\":null,\"modifiers\":[],\"desc\":\"<p style=\'margin-bottom: 15px; line-height: 1.6;\'>You can cast any spell as a Ritual if that spell has the Ritual tag and the spell is in your spellbook. You needn\'t have the spell prepared, but you must read from the book to cast a spell in this way.<\\/p>\"},{\"level\":1,\"name\":\"Arcane Recovery\",\"description\":\"<p style=\'margin-bottom: 15px; line-height: 1.6;\'>You can regain some of your magical energy by studying your spellbook. When you finish a Short Rest, you can choose expended spell slots to recover. The spell slots can have a combined level equal to no more than half your Wizard level (round up), and none of the slots can be level 6 or higher. For example, if you\'re a level 4 Wizard, you can recover up to two levels\' worth of spell slots, regaining either one level 2 spell slot or two level 1 spell slots.<\\/p>\\n<p style=\'margin-bottom: 15px; line-height: 1.6;\'>Once you use this feature, you can\'t do so again until you finish a Long Rest.<\\/p>\",\"mechanics\":null,\"modifiers\":[],\"desc\":\"<p style=\'margin-bottom: 15px; line-height: 1.6;\'>You can regain some of your magical energy by studying your spellbook. When you finish a Short Rest, you can choose expended spell slots to recover. The spell slots can have a combined level equal to no more than half your Wizard level (round up), and none of the slots can be level 6 or higher. For example, if you\'re a level 4 Wizard, you can recover up to two levels\' worth of spell slots, regaining either one level 2 spell slot or two level 1 spell slots.<\\/p>\\n<p style=\'margin-bottom: 15px; line-height: 1.6;\'>Once you use this feature, you can\'t do so again until you finish a Long Rest.<\\/p>\"},{\"level\":2,\"name\":\"Scholar\",\"description\":\"<p style=\'margin-bottom: 15px; line-height: 1.6;\'>While studying magic, you also specialized in another field of study. Choose one of the following skills in which you have proficiency: Arcana, History, Investigation, Medicine, Nature, or Religion. You have Expertise in the chosen skill.<\\/p>\",\"mechanics\":{\"logic\":{\"type\":\"choice\",\"choose\":1,\"options\":[\"Arcana\",\"History\",\"Investigation\",\"Medicine\",\"Nature\",\"Religion\"]}},\"modifiers\":[{\"type\":\"proficiency\",\"sub_type\":\"skill\",\"target\":\"expertise_choice\",\"value\":\"2\"}],\"desc\":\"<p style=\'margin-bottom: 15px; line-height: 1.6;\'>While studying magic, you also specialized in another field of study. Choose one of the following skills in which you have proficiency: Arcana, History, Investigation, Medicine, Nature, or Religion. You have Expertise in the chosen skill.<\\/p>\"},{\"level\":3,\"name\":\"Wizard Subclass\",\"description\":\"<p style=\'margin-bottom: 15px; line-height: 1.6;\'>You gain a Wizard subclass of your choice. The Evoker subclass is detailed after this class\'s description. A subclass is a specialization that grants you features at certain Wizard levels. For the rest of your career, you gain each of your subclass\'s features that are of your Wizard level or lower.<\\/p>\\n<div style=\'background: linear-gradient(135deg, #e0f2fe 0%, #f0f9ff 100%); border-left: 5px solid #0284c7; padding: 15px 20px; border-radius: 0 8px 8px 0; margin: 20px 0; box-shadow: 0 4px 6px rgba(0,0,0,0.05); color: #0f172a; line-height: 1.6;\'><h5 style=\'margin: 0 0 10px 0; color: #0369a1; display: flex; align-items: center; gap: 8px; font-size: 1.05rem;\'><i class=\\\"fa-solid fa-book-journal-whills\\\"><\\/i> <strong>Expanding and Replacing a Spellbook<\\/strong><\\/h5><div style=\'font-size: 0.9rem;\'>**Expanding and Replacing a Spellbook**<br \\/>\\n&gt;<br \\/>\\nThe spells you add to your spellbook as you gain levels reflect your ongoing magical research, but you might find other spells during your adventures that you can add to the book. You could discover a Wizard spell on a _Spell Scroll_, for example, and then copy it into your spellbook.<br \\/>\\n&gt;<br \\/>\\n_Copying a Spell into the Book._ When you find a level 1+ Wizard spell, you can copy it into your spellbook if it&#039;s of a level you can prepare and if you have time to copy it. For each level of the spell, the transcription takes 2 hours and costs 50 GP. Afterward you can prepare the spell like the other spells in your spellbook.<br \\/>\\n&gt;<br \\/>\\n_Copying the Book._ You can copy a spell from your spellbook into another book. This is like copying a new spell into your spellbook but faster, since you already know how to cast the spell. You need spend only 1 hour and 10 GP for each level of the copied spell.<br \\/>\\n&gt;<br \\/>\\nIf you lose your spellbook, you can use the same procedure to transcribe the Wizard spells that you have prepared into a new spellbook. Filling out the remainder of the new book requires you to find new spells to do so. For this reason, many wizards keep a backup spellbook.<\\/div><\\/div>\",\"mechanics\":null,\"modifiers\":[],\"desc\":\"<p style=\'margin-bottom: 15px; line-height: 1.6;\'>You gain a Wizard subclass of your choice. The Evoker subclass is detailed after this class\'s description. A subclass is a specialization that grants you features at certain Wizard levels. For the rest of your career, you gain each of your subclass\'s features that are of your Wizard level or lower.<\\/p>\\n<div style=\'background: linear-gradient(135deg, #e0f2fe 0%, #f0f9ff 100%); border-left: 5px solid #0284c7; padding: 15px 20px; border-radius: 0 8px 8px 0; margin: 20px 0; box-shadow: 0 4px 6px rgba(0,0,0,0.05); color: #0f172a; line-height: 1.6;\'><h5 style=\'margin: 0 0 10px 0; color: #0369a1; display: flex; align-items: center; gap: 8px; font-size: 1.05rem;\'><i class=\\\"fa-solid fa-book-journal-whills\\\"><\\/i> <strong>Expanding and Replacing a Spellbook<\\/strong><\\/h5><div style=\'font-size: 0.9rem;\'>**Expanding and Replacing a Spellbook**<br \\/>\\n&gt;<br \\/>\\nThe spells you add to your spellbook as you gain levels reflect your ongoing magical research, but you might find other spells during your adventures that you can add to the book. You could discover a Wizard spell on a _Spell Scroll_, for example, and then copy it into your spellbook.<br \\/>\\n&gt;<br \\/>\\n_Copying a Spell into the Book._ When you find a level 1+ Wizard spell, you can copy it into your spellbook if it&#039;s of a level you can prepare and if you have time to copy it. For each level of the spell, the transcription takes 2 hours and costs 50 GP. Afterward you can prepare the spell like the other spells in your spellbook.<br \\/>\\n&gt;<br \\/>\\n_Copying the Book._ You can copy a spell from your spellbook into another book. This is like copying a new spell into your spellbook but faster, since you already know how to cast the spell. You need spend only 1 hour and 10 GP for each level of the copied spell.<br \\/>\\n&gt;<br \\/>\\nIf you lose your spellbook, you can use the same procedure to transcribe the Wizard spells that you have prepared into a new spellbook. Filling out the remainder of the new book requires you to find new spells to do so. For this reason, many wizards keep a backup spellbook.<\\/div><\\/div>\"},{\"level\":4,\"name\":\"Ability Score Improvement\",\"description\":\"<p style=\'margin-bottom: 15px; line-height: 1.6;\'>You gain the Ability Score Improvement feat (see \\\"Feats\\\") or another feat of your choice for which you qualify. You gain this feature again at Wizard levels 8, 12, and 16.<\\/p>\",\"mechanics\":null,\"modifiers\":[],\"desc\":\"<p style=\'margin-bottom: 15px; line-height: 1.6;\'>You gain the Ability Score Improvement feat (see \\\"Feats\\\") or another feat of your choice for which you qualify. You gain this feature again at Wizard levels 8, 12, and 16.<\\/p>\"},{\"level\":5,\"name\":\"Memorize Spell\",\"description\":\"<p style=\'margin-bottom: 15px; line-height: 1.6;\'>Whenever you finish a Short Rest, you can study your spellbook and replace one of the level 1+ Wizard spells you have prepared for your Spellcasting feature with another level 1+ spell from the book.<\\/p>\",\"mechanics\":null,\"modifiers\":[],\"desc\":\"<p style=\'margin-bottom: 15px; line-height: 1.6;\'>Whenever you finish a Short Rest, you can study your spellbook and replace one of the level 1+ Wizard spells you have prepared for your Spellcasting feature with another level 1+ spell from the book.<\\/p>\"},{\"level\":6,\"name\":\"Wizard Subclass\",\"description\":\"<p style=\'margin-bottom: 15px; line-height: 1.6;\'>You gain a feature from your Wizard subclass.<\\/p>\",\"mechanics\":null,\"modifiers\":[],\"desc\":\"<p style=\'margin-bottom: 15px; line-height: 1.6;\'>You gain a feature from your Wizard subclass.<\\/p>\"},{\"level\":8,\"name\":\"Ability Score Improvement\",\"description\":\"<p style=\'margin-bottom: 15px; line-height: 1.6;\'>You gain the Ability Score Improvement feat (see &quot;Feats&quot;) or another feat of your choice for which you qualify.<\\/p>\",\"mechanics\":null,\"modifiers\":[],\"desc\":\"<p style=\'margin-bottom: 15px; line-height: 1.6;\'>You gain the Ability Score Improvement feat (see &quot;Feats&quot;) or another feat of your choice for which you qualify.<\\/p>\"},{\"level\":10,\"name\":\"Wizard Subclass\",\"description\":\"<p style=\'margin-bottom: 15px; line-height: 1.6;\'>You gain a feature from your Wizard subclass.<\\/p>\",\"mechanics\":null,\"modifiers\":[],\"desc\":\"<p style=\'margin-bottom: 15px; line-height: 1.6;\'>You gain a feature from your Wizard subclass.<\\/p>\"},{\"level\":12,\"name\":\"Ability Score Improvement\",\"description\":\"<p style=\'margin-bottom: 15px; line-height: 1.6;\'>You gain the Ability Score Improvement feat (see &quot;Feats&quot;) or another feat of your choice for which you qualify.<\\/p>\",\"mechanics\":null,\"modifiers\":[],\"desc\":\"<p style=\'margin-bottom: 15px; line-height: 1.6;\'>You gain the Ability Score Improvement feat (see &quot;Feats&quot;) or another feat of your choice for which you qualify.<\\/p>\"},{\"level\":14,\"name\":\"Wizard Subclass\",\"description\":\"<p style=\'margin-bottom: 15px; line-height: 1.6;\'>You gain a feature from your Wizard subclass.<\\/p>\",\"mechanics\":null,\"modifiers\":[],\"desc\":\"<p style=\'margin-bottom: 15px; line-height: 1.6;\'>You gain a feature from your Wizard subclass.<\\/p>\"},{\"level\":16,\"name\":\"Ability Score Improvement\",\"description\":\"<p style=\'margin-bottom: 15px; line-height: 1.6;\'>You gain the Ability Score Improvement feat (see &quot;Feats&quot;) or another feat of your choice for which you qualify.<\\/p>\",\"mechanics\":null,\"modifiers\":[],\"desc\":\"<p style=\'margin-bottom: 15px; line-height: 1.6;\'>You gain the Ability Score Improvement feat (see &quot;Feats&quot;) or another feat of your choice for which you qualify.<\\/p>\"},{\"level\":18,\"name\":\"Spell Mastery\",\"description\":\"<p style=\'margin-bottom: 15px; line-height: 1.6;\'>You have achieved such mastery over certain spells that you can cast them at will. Choose a level 1 and a level 2 spell in your spellbook that have a casting time of an action. You always have those spells prepared, and you can cast them at their lowest level without expending a spell slot. To cast either spell at a higher level, you must expend a spell slot.<\\/p>\\n<p style=\'margin-bottom: 15px; line-height: 1.6;\'>Whenever you finish a Long Rest, you can study your spellbook and replace one of those spells with an eligible spell of the same level from the book.<\\/p>\",\"mechanics\":null,\"modifiers\":[],\"desc\":\"<p style=\'margin-bottom: 15px; line-height: 1.6;\'>You have achieved such mastery over certain spells that you can cast them at will. Choose a level 1 and a level 2 spell in your spellbook that have a casting time of an action. You always have those spells prepared, and you can cast them at their lowest level without expending a spell slot. To cast either spell at a higher level, you must expend a spell slot.<\\/p>\\n<p style=\'margin-bottom: 15px; line-height: 1.6;\'>Whenever you finish a Long Rest, you can study your spellbook and replace one of those spells with an eligible spell of the same level from the book.<\\/p>\"},{\"level\":19,\"name\":\"Epic Boon\",\"description\":\"<p style=\'margin-bottom: 15px; line-height: 1.6;\'>You gain an Epic Boon feat (see \\\"Feats\\\") or another feat of your choice for which you qualify. Boon of Spell Recall is recommended.<\\/p>\",\"mechanics\":null,\"modifiers\":[],\"desc\":\"<p style=\'margin-bottom: 15px; line-height: 1.6;\'>You gain an Epic Boon feat (see \\\"Feats\\\") or another feat of your choice for which you qualify. Boon of Spell Recall is recommended.<\\/p>\"},{\"level\":20,\"name\":\"Signature Spells\",\"description\":\"<p style=\'margin-bottom: 15px; line-height: 1.6;\'>Choose two level 3 spells in your spellbook as your signature spells. You always have these spells prepared, and you can cast each of them once at level 3 without expending a spell slot. When you do so, you can\'t cast them in this way again until you finish a Short or Long Rest. To cast either spell at a higher level, you must expend a spell slot.<\\/p>\\n<p style=\'margin-bottom: 15px; line-height: 1.6;\'>\\n<p style=\'margin-bottom: 15px; line-height: 1.6;\'>\\n<p style=\'margin-bottom: 15px; line-height: 1.6;\'>### Wizard Spell List<\\/p><p style=\'margin-bottom: 15px; line-height: 1.6;\'>This section presents the Wizard spell list. The spells are organized by spell level and then alphabetized, and each spell\'s school of magic is listed. In the Special column, C means the spell requires Concentration, R means it\'s a Ritual, and M means it requires a specific Material component.<\\/p><p style=\'margin-bottom: 15px; line-height: 1.6;\'>#### Cantrips (Level 0 Wizard Spells)<\\/p><table>\\n  <thead>\\n    <tr>\\n      <th>Spell<\\/th>\\n      <th>School<\\/th>\\n      <th>Special<\\/th>\\n    <\\/tr>\\n  <\\/thead>\\n  <tbody>\\n    <tr>\\n      <td>Acid Splash<\\/td>\\n      <td>Evocation<\\/td>\\n      <td>—<\\/td>\\n    <\\/tr>\\n    <tr>\\n      <td>Chill Touch<\\/td>\\n      <td>Necromancy<\\/td>\\n      <td>—<\\/td>\\n    <\\/tr>\\n    <tr>\\n      <td>Dancing Lights<\\/td>\\n      <td>Illusion<\\/td>\\n      <td>C<\\/td>\\n    <\\/tr>\\n    <tr>\\n      <td>Elementalism<\\/td>\\n      <td>Transmutation<\\/td>\\n      <td>—<\\/td>\\n    <\\/tr>\\n    <tr>\\n      <td>Fire Bolt<\\/td>\\n      <td>Evocation<\\/td>\\n      <td>—<\\/td>\\n    <\\/tr>\\n    <tr>\\n      <td>Light<\\/td>\\n      <td>Evocation<\\/td>\\n      <td>—<\\/td>\\n    <\\/tr>\\n    <tr>\\n      <td>Mage Hand<\\/td>\\n      <td>Conjuration<\\/td>\\n      <td>—<\\/td>\\n    <\\/tr>\\n    <tr>\\n      <td>Mending<\\/td>\\n      <td>Transmutation<\\/td>\\n      <td>—<\\/td>\\n    <\\/tr>\\n    <tr>\\n      <td>Message<\\/td>\\n      <td>Transmutation<\\/td>\\n      <td>—<\\/td>\\n    <\\/tr>\\n    <tr>\\n      <td>Minor Illusion<\\/td>\\n      <td>Illusion<\\/td>\\n      <td>—<\\/td>\\n    <\\/tr>\\n    <tr>\\n      <td>Poison Spray<\\/td>\\n      <td>Necromancy<\\/td>\\n      <td>—<\\/td>\\n    <\\/tr>\\n    <tr>\\n      <td>Prestidigitation<\\/td>\\n      <td>Transmutation<\\/td>\\n      <td>—<\\/td>\\n    <\\/tr>\\n    <tr>\\n      <td>Ray of Frost<\\/td>\\n      <td>Evocation<\\/td>\\n      <td>—<\\/td>\\n    <\\/tr>\\n    <tr>\\n      <td>Shocking Grasp<\\/td>\\n      <td>Evocation<\\/td>\\n      <td>—<\\/td>\\n    <\\/tr>\\n    <tr>\\n      <td>True Strike<\\/td>\\n      <td>Divination<\\/td>\\n      <td>—<\\/td>\\n    <\\/tr>\\n  <\\/tbody>\\n<\\/table><p style=\'margin-bottom: 15px; line-height: 1.6;\'>#### Level 1 Wizard Spells<\\/p><table>\\n  <thead>\\n    <tr>\\n      <th>Spell<\\/th>\\n      <th>School<\\/th>\\n      <th>Special<\\/th>\\n    <\\/tr>\\n  <\\/thead>\\n  <tbody>\\n    <tr>\\n      <td>Alarm<\\/td>\\n      <td>Abjuration<\\/td>\\n      <td>R<\\/td>\\n    <\\/tr>\\n    <tr>\\n      <td>Burning Hands<\\/td>\\n      <td>Evocation<\\/td>\\n      <td>—<\\/td>\\n    <\\/tr>\\n    <tr>\\n      <td>Charm Person<\\/td>\\n      <td>Enchantment<\\/td>\\n      <td>—<\\/td>\\n    <\\/tr>\\n    <tr>\\n      <td>Chromatic Orb<\\/td>\\n      <td>Evocation<\\/td>\\n      <td>M<\\/td>\\n    <\\/tr>\\n    <tr>\\n      <td>Color Spray<\\/td>\\n      <td>Illusion<\\/td>\\n      <td>—<