INSERT INTO `feats` (`feat_id`, `feat_name`, `feat_type`, `prerequisite`, `feat_desc`, `stat_options`, `feat_choices`, `srd_source`, `is_homebrew`, `author_id`, `modifiers`, `deleted_at`) VALUES
('ability-score-improvement', 'Ability Score Improvement', 'General Feat', 'Level 4+', 'Increase one ability score of your choice by 2, or increase two ability scores of your choice by 1. This feat can\'t increase an ability score above 20.\n\n_Repeatable._ You can take this feat more than once.', '{\"type\":\"asi\",\"points\":2,\"max\":20}', NULL, NULL, 0, NULL, '[{\"type\":\"bonus\",\"sub_type\":\"stat\",\"target\":\"strength\",\"value\":\"1\"}]', NULL),
('alert', 'Alert', 'Origin Feat', 'None', 'You gain the following benefits.\n\n_Initiative Proficiency._ When you roll Initiative, you can add your Proficiency Bonus to the roll.\n\n_Initiative Swap._ Immediately after you roll Initiative, you can swap your Initiative with the Initiative of one willing ally in the same combat. You can\'t make this swap if you or the ally has the Incapacitated condition.', NULL, NULL, NULL, 0, NULL, '[{\"type\":\"bonus\",\"sub_type\":\"attack\",\"target\":\"initiative\",\"value\":\"prof\"}]', NULL),
('archery', 'Archery', 'Fighting Style Feat', 'Fighting Style Feature', 'You gain a +2 bonus to attack rolls you make with Ranged weapons.', NULL, NULL, NULL, 0, NULL, '[{\"type\":\"bonus\",\"sub_type\":\"stat\",\"target\":\"strength\",\"value\":\"1\"}]', NULL),
('boon-of-combat-prowess', 'Boon of Combat Prowess', 'Epic Boon Feat', 'Level 19+', 'You gain the following benefits.\n\n_Ability Score Increase._ Increase one ability score of your choice by 1, to a maximum of 30.\n\n_Peerless Aim._ When you miss with an attack roll, you can hit instead. Once you use this benefit, you can\'t use it again until the start of your next turn.', '{\"type\":\"half\",\"choices\":[\"str\",\"dex\",\"con\",\"int\",\"wis\",\"cha\"],\"points\":1,\"max\":30}', NULL, NULL, 0, NULL, '[{\"type\":\"bonus\",\"sub_type\":\"stat\",\"target\":\"strength\",\"value\":\"1\"}]', NULL),
('boon-of-dimensional-travel', 'Boon of Dimensional Travel', 'Epic Boon Feat', 'Level 19+', 'You gain the following benefits.\n\n_Ability Score Increase._ Increase one ability score of your choice by 1, to a maximum of 30.\n\n_Blink Steps._ Immediately after you take the Attack action or the Magic action, you can teleport up to 30 feet to an unoccupied space you can see.', '{\"type\":\"half\",\"choices\":[\"str\",\"dex\",\"con\",\"int\",\"wis\",\"cha\"],\"points\":1,\"max\":30}', NULL, NULL, 0, NULL, '[{\"type\":\"bonus\",\"sub_type\":\"stat\",\"target\":\"strength\",\"value\":\"1\"}]', NULL),
('boon-of-fate', 'Boon of Fate', 'Epic Boon Feat', 'Level 19+', 'You gain the following benefits.\n\n_Ability Score Increase._ Increase one ability score of your choice by 1, to a maximum of 30.\n\n_Improve Fate._ When you or another creature within 60 feet of you succeeds on or fails a D20 Test, you can roll 2d4 and apply the total rolled as a bonus or penalty to the d20 roll. Once you use this benefit, you can\'t use it again until you roll Initiative or finish a Short or Long Rest.', '{\"type\":\"half\",\"choices\":[\"str\",\"dex\",\"con\",\"int\",\"wis\",\"cha\"],\"points\":1,\"max\":30}', NULL, NULL, 0, NULL, '[{\"type\":\"bonus\",\"sub_type\":\"stat\",\"target\":\"strength\",\"value\":\"1\"}]', NULL),
('boon-of-irresistible-offense', 'Boon of Irresistible Offense', 'Epic Boon Feat', 'Level 19+', 'You gain the following benefits.\n\n_Ability Score Increase._ Increase your Strength or Dexterity score by 1, to a maximum of 30.\n\n_Overcome Defenses._ The Bludgeoning, Piercing, and Slashing damage you deal always ignores Resistance.\n\n_Overwhelming Strike._ When you roll a 20 on the d20 for an attack roll, you can deal extra damage to the target equal to the ability score increased by this feat. The extra damage\'s type is the same as the attack\'s type.', '{\"type\":\"half\",\"choices\":[\"str\",\"dex\"],\"points\":1,\"max\":30}', NULL, NULL, 0, NULL, '[{\"type\":\"bonus\",\"sub_type\":\"stat\",\"target\":\"strength\",\"value\":\"1\"}]', NULL),
('boon-of-spell-recall', 'Boon of Spell Recall', 'Epic Boon Feat', 'Level 19+, Spellcasting Feature', 'You gain the following benefits.\n\n_Ability Score Increase._ Increase your Intelligence, Wisdom, or Charisma score by 1, to a maximum of 30.\n\n_Free Casting._ Whenever you cast a spell with a level 1–4 spell slot, roll 1d4. If the number you roll is the same as the slot\'s level, the slot isn\'t expended.', '{\"type\":\"half\",\"choices\":[\"int\",\"wis\",\"cha\"],\"points\":1,\"max\":30}', NULL, NULL, 0, NULL, '[{\"type\":\"bonus\",\"sub_type\":\"stat\",\"target\":\"strength\",\"value\":\"1\"}]', NULL),
('boon-of-the-night-spirit', 'Boon of the Night Spirit', 'Epic Boon Feat', 'Level 19+', 'You gain the following benefits.\n\n_Ability Score Increase._ Increase one ability score of your choice by 1, to a maximum of 30.\n\n_Merge with Shadows._ While within Dim Light or Darkness, you can give yourself the Invisible condition as a Bonus Action. The condition ends on you immediately after you take an action, a Bonus Action, or a Reaction.\n\n_Shadowy Form._ While within Dim Light or Darkness, you have Resistance to all damage except Psychic and Radiant.', '{\"type\":\"half\",\"choices\":[\"str\",\"dex\",\"con\",\"int\",\"wis\",\"cha\"],\"points\":1,\"max\":30}', NULL, NULL, 0, NULL, '[{\"type\":\"bonus\",\"sub_type\":\"stat\",\"target\":\"strength\",\"value\":\"1\"}]', NULL),
('boon-of-truesight', 'Boon of Truesight', 'Epic Boon Feat', 'Level 19+', 'You gain the following benefits.\n\n_Ability Score Increase._ Increase one ability score of your choice by 1, to a maximum of 30.\n\n_Truesight._ You have Truesight with a range of 60 feet.', '{\"type\":\"half\",\"choices\":[\"str\",\"dex\",\"con\",\"int\",\"wis\",\"cha\"],\"points\":1,\"max\":30}', NULL, NULL, 0, NULL, '[{\"type\":\"bonus\",\"sub_type\":\"stat\",\"target\":\"strength\",\"value\":\"1\"}]', NULL),
('defense', 'Defense', 'Fighting Style Feat', 'Fighting Style Feature', 'While you\'re wearing Light, Medium, or Heavy armor, you gain a +1 bonus to Armor Class.', NULL, NULL, NULL, 0, NULL, '[{\"type\":\"bonus\",\"sub_type\":\"stat\",\"target\":\"strength\",\"value\":\"1\"}]', NULL),
('grappler', 'Grappler', 'General Feat', 'Level 4+, Strength or Dexterity 13+', 'You gain the following benefits.\n\n_Ability Score Increase._ Increase your Strength or Dexterity score by 1, to a maximum of 20.\n\n_Punch and Grab._ When you hit a creature with an Unarmed Strike as part of the Attack action on your turn, you can use both the Damage and the Grapple option. You can use this benefit only once per turn.\n\n_Attack Advantage._ You have Advantage on attack rolls against a creature Grappled by you.\n\n_Fast Wrestler._ You don\'t have to spend extra movement to move a creature Grappled by you if the creature is your size or smaller.', '{\"type\":\"half\",\"choices\":[\"str\",\"dex\"],\"points\":1,\"max\":20}', NULL, NULL, 0, NULL, '[{\"type\":\"bonus\",\"sub_type\":\"stat\",\"target\":\"strength\",\"value\":\"1\"}]', NULL),
('great-weapon-fighting', 'Great Weapon Fighting', 'Fighting Style Feat', 'Fighting Style Feature', 'When you roll damage for an attack you make with a Melee weapon that you are holding with two hands, you can treat any 1 or 2 on a damage die as a 3. The weapon must have the Two-Handed or Versatile property to gain this benefit.', NULL, NULL, NULL, 0, NULL, '[{\"type\":\"bonus\",\"sub_type\":\"stat\",\"target\":\"strength\",\"value\":\"1\"}]', NULL),
('magic-initiate', 'Magic Initiate', 'Origin Feat', 'None', 'You gain the following benefits.\n\n_Two Cantrips._ You learn two cantrips of your choice from the Cleric, Druid, or Wizard spell list. Intelligence, Wisdom, or Charisma is your spellcasting ability for this feat\'s spells (choose when you select this feat).\n\n_Level 1 Spell._ Choose a level 1 spell from the same list you selected for this feat\'s cantrips. You always have that spell prepared. You can cast it once without a spell slot, and you regain the ability to cast it in that way when you finish a Long Rest. You can also cast the spell using any spell slots you have.\n\n_Spell Change._ Whenever you gain a new level, you can replace one of the spells you chose for this feat with a different spell of the same level from the chosen spell list.\n\n_Repeatable._ You can take this feat more than once, but you must choose a different spell list each time.', NULL, NULL, NULL, 0, NULL, '[{\"type\":\"bonus\",\"sub_type\":\"stat\",\"target\":\"strength\",\"value\":\"1\"}]', NULL),
('savage-attacker', 'Savage Attacker', 'Origin Feat', 'None', 'You\'ve trained to deal particularly damaging strikes. Once per turn when you hit a target with a weapon, you can roll the weapon\'s damage dice twice and use either roll against the target.', NULL, NULL, NULL, 0, NULL, '[{\"type\":\"bonus\",\"sub_type\":\"stat\",\"target\":\"strength\",\"value\":\"1\"}]', NULL),
('skilled', 'Skilled', 'Origin Feat', 'None', 'You gain proficiency in any combination of three skills or tools of your choice.\n\n_Repeatable._ You can take this feat more than once.', NULL, NULL, NULL, 0, NULL, '[{\"type\":\"proficiency\",\"sub_type\":\"skill\",\"target\":\"choice\",\"value\":\"3\"}]', NULL),
('time-touched', 'Time-Touched', 'Origin Feat', 'None', 'You gain the following benefits:\n\n_Echoes of Another Era._ You gain proficiency in one Skill or Tool of your choice.\n\n_Minor Rewind._ When you or a creature you can see within 30 feet fails an Ability Check or Saving Throw, you can use your Reaction to roll 1d4 and add it to the result. You can use this feature a number of times equal to your Proficiency Bonus, and you regain all expended uses when you finish a Long Rest.\n\n_Temporal Mending._ You learn the Mending cantrip.', NULL, NULL, 'Custom Homebrew', 1, NULL, '[{\"type\":\"bonus\",\"sub_type\":\"stat\",\"target\":\"strength\",\"value\":\"1\"}]', NULL),
('two-weapon-fighting', 'Two-Weapon Fighting', 'Fighting Style Feat', 'Fighting Style Feature', 'When you make an extra attack as a result of using a weapon that has the Light property, you can add your ability modifier to the damage of that attack if you aren\'t already adding it to the damage.', NULL, NULL, NULL, 0, NULL, '[{\"type\":\"bonus\",\"sub_type\":\"stat\",\"target\":\"strength\",\"value\":\"1\"}]', NULL);
