INSERT INTO `weapon_masteries` (`mastery_id`, `mastery_name`, `mastery_desc`, `srd_source`, `is_homebrew`, `author_id`) VALUES
('cleave', 'Cleave', '{\r\n  \"logic\": {\r\n    \"trigger\": \"melee_hit\",\r\n    \"effect\": \"extra_attack\",\r\n    \"target\": \"secondary_creature_within_5ft\",\r\n    \"damage_modifier\": \"base_only_unless_negative\",\r\n    \"usage_limit\": \"once_per_turn\"\r\n  },\r\n  \"display\": \"If you hit a creature with a melee attack roll using this weapon, you can make a melee attack roll with the weapon against a second creature within 5 feet of the first that is also within your reach. On a hit, the second creature takes the weapon\'s damage, but don\'t add your ability modifier to that damage unless that modifier is negative. You can make this extra attack only once per turn.\"\r\n}', 'SRD 5.2.1, Page 42', 0, NULL),
('graze', 'Graze', '{\r\n  \"logic\": {\r\n    \"trigger\": \"melee_miss\",\r\n    \"effect\": \"deal_damage\",\r\n    \"damage_amount\": \"ability_modifier\",\r\n    \"damage_type\": \"weapon_base_type\"\r\n  },\r\n  \"display\": \"If your attack roll with this weapon misses a creature, you can deal damage to that creature equal to the ability modifier you used to make the attack roll. This damage is the same type dealt by the weapon, and the damage can\'t be increased in any way, other than increasing the ability modifier.\"\r\n}', 'SRD 5.2.1, Page 42', 0, NULL),
('nick', 'Nick', '{\r\n  \"logic\": {\r\n    \"trigger\": \"light_weapon_extra_attack\",\r\n    \"effect\": \"make_attack_part_of_attack_action\",\r\n    \"saves_action\": \"bonus_action\",\r\n    \"usage_limit\": \"once_per_turn\"\r\n  },\r\n  \"display\": \"When you make the extra attack of the Light property, you can make it as part of the Attack action instead of as a Bonus Action. You can make this extra attack only once per turn.\"\r\n}', 'SRD 5.2.1, Page 42', 0, NULL),
('push', 'Push', '{\r\n  \"logic\": {\r\n    \"trigger\": \"hit\",\r\n    \"effect\": \"push_target\",\r\n    \"distance\": 10,\r\n    \"target_size_limit\": \"Large or smaller\"\r\n  },\r\n  \"display\": \"If you hit a creature with this weapon, you can push the creature up to 10 feet straight away from you if it is Large or smaller.\"\r\n}', 'SRD 5.2.1, Page 42', 0, NULL),
('sap', 'Sap', '{\r\n  \"logic\": {\r\n    \"trigger\": \"hit\",\r\n    \"effect\": \"disadvantage_next_attack\",\r\n    \"duration\": \"start_of_your_next_turn\"\r\n  },\r\n  \"display\": \"If you hit a creature with this weapon, that creature has Disadvantage on its next attack roll before the start of your next turn.\"\r\n}', 'SRD 5.2.1, Page 42', 0, NULL),
('slow', 'Slow', '{\r\n  \"logic\": {\r\n    \"trigger\": \"hit\",\r\n    \"effect\": \"reduce_speed\",\r\n    \"speed_reduction\": 10,\r\n    \"duration\": \"start_of_your_next_turn\"\r\n  },\r\n  \"display\": \"If you hit a creature with this weapon and deal damage to it, you can reduce its Speed by 10 feet until the start of your next turn. If you hit the creature more than once with this property, the Speed reduction doesn\'t exceed 10 feet.\"\r\n}', 'SRD 5.2.1, Page 42', 0, NULL),
('topple', 'Topple', '{\r\n  \"logic\": {\r\n    \"trigger\": \"hit\",\r\n    \"effect\": \"knock_prone\",\r\n    \"saving_throw\": \"Constitution\",\r\n    \"save_dc\": \"8 + proficiency_bonus + (STR or DEX modifier)\"\r\n  },\r\n  \"display\": \"If you hit a creature with this weapon, you can force the creature to make a Constitution saving throw. On a failed save, the creature has the Prone condition. The DC is 8 + your Proficiency Bonus + the ability modifier used to make the attack roll.\"\r\n}', 'SRD 5.2.1, Page 42', 0, NULL),
('vex', 'Vex', '{\r\n  \"logic\": {\r\n    \"trigger\": \"hit_and_damage\",\r\n    \"effect\": \"advantage_next_attack\",\r\n    \"duration\": \"end_of_your_next_turn\"\r\n  },\r\n  \"display\": \"If you hit a creature with this weapon and deal damage to the creature, you have Advantage on your next attack roll against that creature before the end of your next turn.\"\r\n}', 'SRD 5.2.1, Page 42', 0, NULL);
